    return () => clearInterval(timer);
  }, [messages]);
  return (
    <div className="text-center space-y-6 py-12">
      <div className="relative w-24 h-24 mx-auto">
        <div className="absolute inset-0 bg-primary-500/20 rounded-full animate-ping"></div>
