      </div>
      <div className="space-y-2">
        <p className="text-[0.65rem] font-black uppercase text-primary-500 tracking-[0.4em] animate-pulse">
          {messages[msgIndex]}
        </p>
        <div className="w-48 h-1 bg-gray-200 dark:bg-white/10 mx-auto rounded-full overflow-hidden">
          <div className="h-full bg-primary-500 animate-shimmer" style={{ width: '60%' }}></div>
        </div>
      </div>
    </div>
  );
};

