import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface ClaimPart {
  namaPart: string;
  kondisi: string;
  tindakan: 'Perbaiki' | 'Ganti';
  estimasiBiaya: number;
}

export interface ClaimAnalysisData {
  severity: 'Ringan' | 'Sedang' | 'Berat' | 'Total Loss';
  totalEstimasi: number;
  rincianPart: ClaimPart[];
  aiInsight: string;
  rekomendasiBengkel: string;
  photoId?: string; // Used for consistency tracking
}

// Simple in-memory cache to ensure identical results for identical images
const claimCache = new Map<string, ClaimAnalysisData>();

const getImageHash = (base64: string): string => {
  // Simple "fingerprint" using length and slices of the string
  return `${base64.length}-${base64.substring(0, 100)}-${base64.substring(base64.length - 100)}`;
};

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const hash = getImageHash(base64Image);

  // Return cached result if available to ensure 100% consistency for same photo
  if (claimCache.has(hash)) {
    console.log("Neural Cache Hit: Returning identical analysis for consistency.");
    return { success: true, data: claimCache.get(hash) };
  }

  const modelId = 'gemini-3-flash-preview';
  const prompt = `Anda adalah auditor klaim asuransi profesional. Analisa foto kerusakan kendaraan ini dengan tingkat akurasi tinggi.

  TUGAS:
  1. Identifikasi komponen yang rusak secara visual.
  2. Tentukan apakah komponen harus diperbaiki (baret/penyok ringan) atau diganti (pecah/hancur).
  3. Berikan estimasi biaya perbaikan dalam Rupiah (IDR).
  4. Berikan insight teknis tentang tingkat keparahan.

  FORMAT JSON:
  {
    "severity": "Ringan" | "Sedang" | "Berat" | "Total Loss",
    "totalEstimasi": number,
    "rincianPart": [{ "namaPart": "string", "kondisi": "string", "tindakan": "Perbaiki" | "Ganti", "estimasiBiaya": number }],
    "aiInsight": "string",
    "rekomendasiBengkel": "string"
  }`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: "application/json",
        temperature: 0.1, // Lower temperature for more deterministic/consistent results
        topP: 0.1
      }
    });

    const data: ClaimAnalysisData = JSON.parse(response.text);
    data.photoId = hash;

    // Cache the result
    claimCache.set(hash, data);

    return { success: true, data };
  } catch (error) {
    console.error("AI Analysis Error:", error);
    return { success: false, error: "Gagal menganalisa klaim. Pastikan foto jelas dan berformat JPEG/PNG." };
  }
};

export const extractKtpData = async (base64: string): Promise<{ success: boolean; data?: any }> => {
  try {
    const cleanBase64 = base64.split(',')[1];
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { text: "Extract data from this Indonesian KTP: Name, KTP Number, Address. Return JSON." },
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ]
      },
      config: { responseMimeType: 'application/json' }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (e) {
    return { success: false };
  }
};

