      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { text: "Extract Name, KTP Number, Address from this KTP. JSON format." },
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ]
      },
      config: { responseMimeType: 'application/json' }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (e) {
    return { success: false };
  }
};

import React, { useState, useMemo } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2 } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, ClaimAnalysisData, DocumentSummary } from '../services/geminiService';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const ClaimManager = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState<'upload' | 'analyzing' | 'result' | 'docUpload' | 'docSummary' | 'reporting' | 'success'>('upload');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [docSummary, setDocSummary] = useState<DocumentSummary | null>(null);
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Date range for validation: Last 7 days
  const dateLimits = useMemo(() => {
    const today = new Date();
    const max = today.toISOString().split('T')[0];
    const minDate = new Date();
    minDate.setDate(today.getDate() - 7);
    const min = minDate.toISOString().split('T')[0];
    return { min, max };
  }, []);

  const handleClaimUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await analyzeClaimPhoto(base64);
      if (response.success && response.data) {
        setClaimResult(response.data);
        setStep('result');
      } else {
        alert(response.error || 'Audit neural gagal. Mohon gunakan foto yang lebih jelas.');
        setStep('upload');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleDocUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsSummarizing(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await summarizeClaimDocument(base64);
      setIsSummarizing(false);
      if (response.success && response.data) {
        setDocSummary(response.data);
        setStep('docSummary');
      } else {
        alert(response.error || 'Gagal meringkas dokumen.');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert("Berikan kronologi lebih detail (min. 20 karakter).");
      return;
    }
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setStep('success');
    }, 1500);
  };

  const Header = ({ title }: { title: string }) => (
    <div className="flex items-center gap-3 mb-4">
      <div className="w-8 h-8 bg-primary-500/10 rounded-lg flex items-center justify-center text-primary-500">
        <AlertCircle size={18}/>
      </div>
      <h3 className="text-xl font-black uppercase tracking-tight">{title}</h3>
    </div>
  );

  if (step === 'upload') {
    return (
      <div className="space-y-4 animate-fade-in flex flex-col h-full justify-center py-4">
        <div className="aspect-[4/3] relative rounded-[2.5rem] overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/30 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-16 h-16 bg-primary-500/10 rounded-full flex items-center justify-center text-primary-500 mb-3 group-hover:scale-110 transition-transform">
            <Camera size={32} />
          </div>
          <p className="text-lg font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors">Neural Scan Kerusakan</p>
          <p className="text-[0.55rem] text-gray-400 mt-1 font-bold uppercase tracking-widest">Klik untuk unggah foto kejadian</p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleClaimUpload} />
        </div>
        <div className="grid grid-cols-2 gap-3">
          <div className="p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-2">
            <Scan size={20} className="text-primary-500" />
            <p className="text-[0.5rem] font-black uppercase tracking-widest text-gray-500">Deterministic Audit</p>
          </div>
          <div className="p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-2">
            <Smartphone size={20} className="text-primary-500" />
            <p className="text-[0.5rem] font-black uppercase tracking-widest text-gray-500">Mobile Proofing</p>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[2.5rem] p-8 animate-pop-in text-center space-y-6 flex flex-col h-full justify-center">
        <div className="relative w-20 h-20 mx-auto">
          <div className="absolute inset-0 bg-primary-500/20 rounded-full animate-ping"></div>
          <div className="relative w-20 h-20 bg-primary-500/10 rounded-full flex items-center justify-center border-2 border-primary-500/30">
            <BrainCircuit size={40} className="text-primary-500 animate-pulse" />
          </div>
        </div>
        <div className="space-y-2">
          <p className="text-[0.6rem] font-black uppercase text-primary-500 tracking-[0.4em] animate-pulse">Analyzing Neural Matrix...</p>
          <div className="w-40 h-1 bg-gray-200 dark:bg-white/10 mx-auto rounded-full overflow-hidden">
            <div className="h-full bg-primary-500 animate-shimmer" style={{ width: '60%' }}></div>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'result' && claimResult) {
    return (
      <div className="space-y-4 animate-pop-in h-full flex flex-col">
        <div className="p-6 glass-card rounded-[2.5rem] border-2 border-primary-500/20 bg-primary-500/5 relative overflow-hidden flex-shrink-0">
          <div className="absolute top-4 right-4">
            <div className="px-3 py-1 bg-primary-500 text-white rounded-full font-black text-[0.55rem] uppercase tracking-widest">{claimResult.severity}</div>
          </div>
          <p className="text-[0.55rem] font-black uppercase text-primary-500 tracking-[0.3em] mb-2">Estimasi Audit AI</p>
          <h3 className="text-4xl font-black tracking-tighter mb-2">{formatIDR(claimResult.totalEstimasi)}</h3>
          <p className="text-xs font-bold text-gray-500 leading-tight">"{claimResult.aiInsight.substring(0, 80)}..."</p>
        </div>

        <div className="flex-1 overflow-y-auto pr-1 no-scrollbar space-y-3">
          <h5 className="font-black uppercase text-[0.55rem] tracking-widest text-gray-400 ml-2">Damage Breakdown</h5>
          {claimResult.rincianPart.map((p, i) => (
            <div key={i} className="p-3 bg-white dark:bg-white/5 rounded-2xl border border-black/5 flex items-center justify-between">
              <div>
                <p className="font-black uppercase text-[0.65rem]">{p.namaPart}</p>
                <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">{p.kondisi}</p>
              </div>
              <div className="text-right">
                <p className="font-black text-xs text-primary-500">{formatIDR(p.estimasiBiaya)}</p>
                <p className={`text-[0.45rem] font-black uppercase tracking-widest px-1.5 py-0.5 rounded-md inline-block ${p.tindakan === 'Ganti' ? 'bg-rose-500 text-white' : 'bg-blue-500 text-white'}`}>{p.tindakan}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-2 gap-3 pt-2">
          <button onClick={() => setStep('docUpload')} className="py-4 bg-white dark:bg-white/5 border border-black/5 rounded-2xl font-black uppercase text-[0.55rem] tracking-widest flex items-center justify-center gap-2">
            <FileSearch size={14}/> Summarize Docs
          </button>
          <button onClick={() => setStep('reporting')} className="py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-[0.55rem] tracking-widest shadow-lg shadow-primary-500/20">Lanjut Lapor</button>
        </div>
      </div>
    );
  }

  if (step === 'docUpload') {
    return (
      <div className="space-y-6 animate-fade-in flex flex-col h-full justify-center">
        <Header title="AI Document Summary" />
        <div className="p-8 rounded-[2.5rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center text-center gap-4 relative">
          {isSummarizing ? (
            <div className="py-8 space-y-4">
              <Loader2 className="animate-spin text-primary-500 mx-auto" size={32}/>
              <p className="text-[0.6rem] font-black uppercase text-gray-400 animate-pulse">Extracting Key Data...</p>
            </div>
          ) : (
            <>
              <FileSearch size={40} className="text-gray-300"/>
              <div className="space-y-1">
                <p className="font-black text-sm uppercase">Upload Dokumen Klaim</p>
                <p className="text-[0.55rem] font-bold text-gray-400 tracking-wider">Polis, Laporan Polisi, atau Bukti Medis</p>
              </div>
              <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleDocUpload} />
            </>
          )}
        </div>
        <button onClick={() => setStep('result')} className="w-full py-4 text-[0.6rem] font-black uppercase text-gray-400 tracking-widest">Kembali ke Hasil Audit</button>
      </div>
    );
  }

  if (step === 'docSummary' && docSummary) {
    return (
      <div className="space-y-4 animate-pop-in h-full flex flex-col">
        <Header title="Neural Summary" />
        <div className="p-5 bg-primary-500/5 border border-primary-500/20 rounded-2xl space-y-2">
          <p className="text-[0.5rem] font-black text-primary-500 uppercase tracking-widest">Policy Identifier</p>
          <p className="font-black text-lg tracking-tight uppercase">{docSummary.policyNumber}</p>
        </div>
        <div className="flex-1 overflow-y-auto space-y-4 no-scrollbar">
          <div className="space-y-2">
             <p className="text-[0.55rem] font-black uppercase text-gray-400 ml-2">Key Information</p>
             <div className="grid gap-2">
               {docSummary.keyPoints.map((point, i) => (
                 <div key={i} className="flex gap-3 p-3 bg-white dark:bg-white/5 border border-black/5 rounded-2xl text-[0.65rem] font-medium items-start">
                   <div className="w-4 h-4 rounded-full bg-emerald-500/10 flex items-center justify-center text-emerald-500 mt-0.5 flex-shrink-0">
                     <CheckCircle2 size={10}/>
                   </div>
                   {point}
                 </div>
               ))}
             </div>
          </div>
          <div className="p-4 bg-gray-100 dark:bg-white/5 rounded-2xl space-y-1">
            <p className="text-[0.5rem] font-black uppercase text-gray-400">AI Risk Assessment</p>
            <p className="text-[0.65rem] italic font-bold leading-snug">{docSummary.riskAssessment}</p>
          </div>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={() => setStep('docUpload')} className="py-4 bg-gray-100 dark:bg-white/5 rounded-2xl font-black uppercase text-[0.55rem] tracking-widest">Re-Upload</button>
          <button onClick={() => setStep('reporting')} className="py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-[0.55rem] tracking-widest shadow-lg">Confirm & Lapor</button>
        </div>
      </div>
    );
  }

  if (step === 'reporting') {
    return (
      <div className="animate-fade-in flex flex-col h-full">
        <div className="flex items-center justify-between mb-4">
          <Header title="Laporan Kejadian" />
          <button onClick={() => setStep('result')} className="p-2 text-gray-400 hover:text-primary-500"><Trash2 size={18}/></button>
        </div>

        <form onSubmit={handleFinalReport} className="flex-1 overflow-y-auto pr-1 no-scrollbar space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <label className="text-[0.55rem] font-black uppercase tracking-widest text-gray-400 ml-2">Tanggal (Max 7 Hari)</label>
              <div className="relative">
                <Calendar size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="date" required 
                  min={dateLimits.min} max={dateLimits.max}
                  className="w-full pl-9 pr-3 py-3 rounded-2xl bg-white dark:bg-white/5 border border-black/5 text-xs outline-none focus:border-primary-500 font-bold" 
                  value={reportForm.date}
                  onChange={(e) => setReportForm({...reportForm, date: e.target.value})}
                />
              </div>
            </div>
            <div className="space-y-1.5">
              <label className="text-[0.55rem] font-black uppercase tracking-widest text-gray-400 ml-2">Waktu Kejadian</label>
              <div className="relative">
                <Clock size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="time" required 
                  className="w-full pl-9 pr-3 py-3 rounded-2xl bg-white dark:bg-white/5 border border-black/5 text-xs outline-none focus:border-primary-500 font-bold" 
                  value={reportForm.time}
                  onChange={(e) => setReportForm({...reportForm, time: e.target.value})}
                />
              </div>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-[0.55rem] font-black uppercase tracking-widest text-gray-400 ml-2">Lokasi</label>
            <div className="relative">
              <MapPin size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-primary-500" />
              <input 
                type="text" required placeholder="Cari Lokasi..."
                className="w-full pl-9 pr-3 py-3 rounded-2xl bg-white dark:bg-white/5 border border-black/5 text-xs outline-none focus:border-primary-500 font-bold" 
                value={reportForm.location}
                onChange={(e) => setReportForm({...reportForm, location: e.target.value})}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-[0.55rem] font-black uppercase tracking-widest text-gray-400 ml-2">Kronologi</label>
            <div className="relative">
              <textarea 
                required rows={3} placeholder="Ceritakan detail kejadian..."
                className="w-full px-4 py-3 rounded-2xl bg-white dark:bg-white/5 border border-black/5 text-xs outline-none focus:border-primary-500 resize-none font-medium leading-snug" 
                value={reportForm.chronology}
                onChange={(e) => setReportForm({...reportForm, chronology: e.target.value})}
              />
            </div>
          </div>

          <div className="p-3 rounded-2xl bg-white dark:bg-white/5 border border-black/5 flex items-center justify-between">
            <span className="text-[0.6rem] font-black uppercase tracking-tight">Keterlibatan Pihak ke-3</span>
