              type="checkbox" 
              className="w-5 h-5 accent-primary-500 rounded-lg"
              checked={reportForm.thirdPartyInvolved}
              onChange={(e) => setReportForm({...reportForm, thirdPartyInvolved: e.target.checked})}
            />
          </div>
        </form>

        <button 
          onClick={handleFinalReport} disabled={isSubmitting}
          className="mt-4 w-full py-5 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] shadow-xl flex items-center justify-center gap-3 disabled:opacity-50"
        >
          {isSubmitting ? <Loader2 className="animate-spin" size={16}/> : <CheckCircle2 size={16}/>}
          Submit Laporan Klaim
        </button>
      </div>
    );
  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-6 py-6 animate-pop-in flex flex-col h-full justify-center">
        <div className="w-24 h-24 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl shadow-emerald-500/30">
          <CheckCircle2 size={48} strokeWidth={3} />
