import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface ClaimPart {
  namaPart: string;
  kondisi: string;
  tindakan: 'Perbaiki' | 'Ganti';
  estimasiBiaya: number;
}

export interface ClaimAnalysisData {
  severity: 'Ringan' | 'Sedang' | 'Berat' | 'Total Loss';
  totalEstimasi: number;
  rincianPart: ClaimPart[];
  aiInsight: string;
  technicalReasoning: string; // New field for detailed explanation
  rekomendasiBengkel: string;
  nextSteps: string[]; // Structured recommendations
  photoId?: string;
}

export interface DocumentSummary {
  policyNumber: string;
  incidentDate: string;
  keyPoints: string[];
  riskAssessment: string;
}

const claimCache = new Map<string, ClaimAnalysisData>();

const getImageHash = (base64: string): string => {
  return `${base64.length}-${base64.substring(0, 100)}-${base64.substring(base64.length - 100)}`;
};

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const hash = getImageHash(base64Image);

  if (claimCache.has(hash)) {
    return { success: true, data: claimCache.get(hash) };
  }

  const modelId = 'gemini-3-flash-preview';
  const prompt = `Anda adalah auditor klaim asuransi senior dengan keahlian neural vision. Analisa foto kerusakan kendaraan ini secara mendalam.

  TUGAS:
  1. Identifikasi kerusakan mikro dan makro.
  2. Berikan "Technical Reasoning" (Mengapa tingkat keparahan dipilih? Misal: Kerusakan struktural vs estetika).
  3. Berikan rincian biaya IDR yang realistis untuk pasar Indonesia.
  4. Berikan daftar "Next Steps" praktis bagi pengguna.

  FORMAT JSON:
  {
    "severity": "Ringan"|"Sedang"|"Berat"|"Total Loss",
    "totalEstimasi": number,
    "rincianPart": [{ "namaPart": "string", "kondisi": "string", "tindakan": "Perbaiki"|"Ganti", "estimasiBiaya": number }],
    "aiInsight": "Ringkasan eksekutif singkat",
    "technicalReasoning": "Penjelasan mendalam tentang bukti visual yang ditemukan (misal: deformasi panel, pecah polimer, dsb)",
    "rekomendasiBengkel": "Tipe bengkel (Authorized/General)",
    "nextSteps": ["Langkah 1", "Langkah 2"]
  }`;

  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { 
        parts: [
          { text: prompt }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: "application/json",
        temperature: 0.1,
        topP: 0.1
      }
    });

    const data: ClaimAnalysisData = JSON.parse(response.text);
    data.photoId = hash;
    claimCache.set(hash, data);
    return { success: true, data };
  } catch (error) {
    return { success: false, error: "Gagal menganalisa klaim secara mendalam. Gunakan foto yang lebih jelas." };
  }
};

