        parts: [
          { text: "Ringkas dokumen klaim ini. Ekstrak data krusial: No Polis, Tanggal, Poin-poin klaim, dan evaluasi risiko AI. Return JSON: { policyNumber: string, incidentDate: string, keyPoints: string[], riskAssessment: string }" },
