            <button onClick={() => setActiveTab('reasoning')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'reasoning' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>AI Reasoning</button>
            <button onClick={() => setActiveTab('steps')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'steps' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Next Actions</button>
