                    <p className="font-black uppercase text-[0.55rem] tracking-tight">{p.namaPart}</p>
                    <p className="text-[0.4rem] font-bold text-gray-400 uppercase tracking-widest">{p.kondisi}</p>
                  </div>
                  <div className="text-right">
                    <p className="font-black text-[0.65rem] text-primary-500">{formatIDR(p.estimasiBiaya)}</p>
                    <p className={`text-[0.4rem] font-black uppercase tracking-widest px-1 py-0.25 rounded-sm inline-block ${p.tindakan === 'Ganti' ? 'bg-rose-500 text-white' : 'bg-blue-500 text-white'}`}>{p.tindakan}</p>
