                    <p className="text-[0.6rem] text-gray-600 dark:text-gray-300 leading-relaxed font-medium">
                        {claimResult.technicalReasoning}
                    </p>
                </div>
                <div className="bg-gray-50 dark:bg-white/5 p-3 rounded-xl border border-gray-100 dark:border-white/5">
                    <p className="text-[0.5rem] font-black uppercase text-gray-400 mb-1">Workshop Recommendation</p>
                    <p className="text-[0.6rem] font-bold uppercase tracking-tight text-gray-900 dark:text-white">{claimResult.rekomendasiBengkel}</p>
                    <p className="text-[0.45rem] text-gray-400 mt-0.5">Based on damage complexity and policy tier.</p>
                </div>
            </div>
          )}

          {activeTab === 'steps' && (
            <div className="animate-fade-in space-y-2 p-1">
