            <FileSearch size={14}/> Summarize Docs
          </button>
          <button onClick={() => setStep('reporting')} className="py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.5rem] tracking-widest shadow-lg shadow-primary-500/20 transition-all active:scale-95">Lanjut Lapor</button>
        </div>
      </div>
    );
