        </div>
        <div className="grid grid-cols-2 gap-2 pt-2">
          <button onClick={() => setStep('docUpload')} className="py-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl font-black uppercase text-[0.5rem] tracking-widest">Retry Scan</button>
