import { useState } from 'react';
import { ChevronRight } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, ClaimAnalysisData, DocumentSummary } from '../services/geminiService';
import { Language } from '../constants';

interface ClaimManagerProps {
  lang: Language;
}

const ClaimManager: React.FC<ClaimManagerProps> = ({ lang }) => {
  const [file, setFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<ClaimAnalysisData | null>(null);
  const [summaryResult, setSummaryResult] = useState<DocumentSummary | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (selectedFile) {
      setFile(selectedFile);
    }
  };

  const handleAnalyzePhoto = async () => {
    if (!file) {
      setError('Please select a file.');
      return;
    }

    try {
      setIsLoading(true);
      setError(null);
      const result = await analyzeClaimPhoto(file);
      setAnalysisResult(result);
      setImageUrl(URL.createObjectURL(file)); // Create a URL for the image
    } catch (err: any) {
      setError(err?.message || 'Failed to analyze the photo.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSummarizeDocument = async () => {
    if (!file) {
      setError('Please select a file.');
      return;
    }

    try {
      setIsLoading(true);
      setError(null);
      const result = await summarizeClaimDocument(file);
      setSummaryResult(result);
      setImageUrl(URL.createObjectURL(file)); // Create a URL for the image
    } catch (err: any) {
      setError(err?.message || 'Failed to summarize the document.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div>
      <input type="file" onChange={handleFileChange} />
      <button onClick={handleAnalyzePhoto} disabled={isLoading}>
        Analyze Photo
      </button>
      <button onClick={handleSummarizeDocument} disabled={isLoading}>
        Summarize Document
      </button>
      {isLoading && <p>Loading...</p>}
      {error && <p style={{ color: 'red' }}>Error: {error}</p>}
      {imageUrl && (
        <img src={imageUrl} alt="Uploaded" style={{ maxWidth: '100%', maxHeight: '200px' }} />
      )}
      {analysisResult && (
        <div>
          <h3>Analysis Result</h3>
          <p>{analysisResult.analysis}</p>
        </div>
      )}
      {summaryResult && (
        <div>
          <h3>Summary Result</h3>
          <p>{summaryResult.summary}</p>
        </div>
      )}
    </div>
  );
};

export default ClaimManager;
</file>
