export default ClaimManager;

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface ClaimPart {
  namaPart: string;
  kondisi: string;
  tindakan: 'Perbaiki' | 'Ganti';
  estimasiBiaya: number;
}

export interface ClaimAnalysisData {
  severity: 'Ringan' | 'Sedang' | 'Berat' | 'Total Loss';
  totalEstimasi: number;
  rincianPart: ClaimPart[];
  aiInsight: string;
  technicalReasoning: string;
  rekomendasiBengkel: string;
  nextSteps: string[];
  photoId?: string;
}

export interface DocumentSummary {
  policyNumber: string;
  incidentDate: string;
  keyPoints: string[];
  riskAssessment: string;
}

export const analyzeClaimPhoto = async (base64Image: string): Promise<{ success: boolean; data?: ClaimAnalysisData; error?: string }> => {
  const modelId = 'gemini-3-flash-preview';
  const prompt = `Anda adalah auditor klaim asuransi senior. Analisa foto kerusakan ini. JSON: { "severity": "string", "totalEstimasi": number, "rincianPart": [], "aiInsight": "string", "technicalReasoning": "string", "rekomendasiBengkel": "string", "nextSteps": [] }`;
  try {
    const cleanBase64 = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;
    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: [{ text: prompt }, { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }] },
      config: { responseMimeType: "application/json", temperature: 0.1 }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (error) { return { success: false, error: "AI Error" }; }
};

export const summarizeClaimDocument = async (base64Doc: string): Promise<{ success: boolean; data?: DocumentSummary; error?: string }> => {
  try {
    const cleanBase64 = base64Doc.includes(',') ? base64Doc.split(',')[1] : base64Doc;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: "Ringkas dokumen klaim ini. JSON: { policyNumber: string, incidentDate: string, keyPoints: string[], riskAssessment: string }" }, { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }] },
      config: { responseMimeType: 'application/json' }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (e) { return { success: false, error: "AI Error" }; }
};

export const extractStnkData = async (base64: string): Promise<{ success: boolean; data?: any }> => {
  try {
    const cleanBase64 = base64.split(',')[1];
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: "Extract STNK data: Plate, Brand, Model, Year, EngineNo. Return JSON." }, { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }] },
      config: { responseMimeType: 'application/json' }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (e) { return { success: false }; }
};

export const analyzeVehicleSurvey = async (images: string[]): Promise<{ success: boolean; score?: number; issues?: string[] }> => {
  try {
    const parts = images.map(img => ({ inlineData: { mimeType: 'image/jpeg', data: img.split(',')[1] } }));
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: "Score vehicle condition 0-100 (80+ for good condition). Detect damage, photo clarity, and STNK consistency. Return JSON: { score: number, issues: string[] }" }, ...parts] },
      config: { responseMimeType: 'application/json' }
    });
    return { success: true, ...JSON.parse(response.text) };
  } catch (e) { return { success: false }; }
};

export const extractKtpData = async (base64: string): Promise<{ success: boolean; data?: any }> => {
