          <p className="text-[0.6rem] font-bold">Region {vehicle.region}: {vehicle.region === '1' ? 'Sumatera' : vehicle.region === '2' ? 'DKI/Jabar/Banten' : 'Lainnya'}</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2">
         {['PRIVATE', 'COMMERCIAL', 'DINAS'].map(u => (
           <button 
             key={u}
             onClick={() => setVehicle({...vehicle, usage: u as any})}
             className={`py-2 rounded-lg text-[0.55rem] font-black uppercase tracking-widest transition-all ${vehicle.usage === u ? 'bg-primary-500 text-white shadow-lg' : 'bg-gray-100 dark:bg-white/5 text-gray-400'}`}
           >{u}</button>
         ))}
      </div>
    </div>
  );

  const StepCoverage = () => (
    <div className="space-y-3 animate-fade-in">
       <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl">
