              onChange={(e) => setCoverage({...coverage, discountType: e.target.value as any})}
            >
              <option value="NOMINAL">IDR</option>
              <option value="PERCENT">%</option>
            </select>
          </div>
       </div>
    </div>
  );

  const StepProviders = () => (
    <div className="space-y-2 animate-fade-in">
       {providerDetails.map(p => (
         <div 
           key={p.id} 
           onClick={() => setSelectedProvider(p.id)}
           className={`p-4 rounded-2xl border-2 cursor-pointer transition-all ${selectedProvider === p.id ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5 opacity-80'}`}
         >
           <div className="flex justify-between items-start mb-2">
              <div className="flex items-center gap-2">
