          <input placeholder="Nomor KTP" value={kycData.ktp} className="p-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-xs font-bold" onChange={(e) => setKycData({...kycData, ktp: e.target.value})}/>
          <input placeholder="Email" value={kycData.email} className="p-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-xs font-bold" onChange={(e) => setKycData({...kycData, email: e.target.value})}/>
          <input placeholder="Nomor HP" value={kycData.phone} className="p-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-xs font-bold" onChange={(e) => setKycData({...kycData, phone: e.target.value})}/>
       </div>
