              value={coverage.discountType}
              onChange={(e) => setCoverage({...coverage, discountType: e.target.value as any})}
            >
              <option value="NOMINAL">IDR</option>
              <option value="PERCENT">%</option>
            </select>
          </div>
       </div>
    </div>
  );

  const StepProviders = () => (
    <div className="space-y-2 animate-fade-in">
       {providerDetails.map(p => (
         <div 
           key={p.id} 
           onClick={() => setSelectedProvider(p.id)}
           className={`p-4 rounded-2xl border-2 cursor-pointer transition-all ${selectedProvider === p.id ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5 opacity-80'}`}
         >
           <div className="flex justify-between items-start mb-2">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-gray-200 dark:bg-white/10 rounded-lg flex items-center justify-center font-black text-[0.6rem]">{p.name[0]}</div>
                <h4 className="font-black text-xs uppercase tracking-tight">{p.name}</h4>
              </div>
              <div className="text-right">
                <p className="text-xs font-black text-primary-500">{formatIDR(calculatedPremium + p.fee + STAMP_DUTY)}</p>
                <p className="text-[0.45rem] text-gray-400 uppercase font-bold">Total Annual</p>
              </div>
           </div>
           <div className="flex gap-2 flex-wrap">
              <div className="px-2 py-0.5 bg-emerald-500/10 text-emerald-500 rounded font-black text-[0.45rem] uppercase">Path Coins: {p.coins * 100}%</div>
              <div className="px-2 py-0.5 bg-blue-500/10 text-blue-500 rounded font-black text-[0.45rem] uppercase">Admin Fee: {formatIDR(p.fee)}</div>
              <div className="px-2 py-0.5 bg-amber-500/10 text-amber-500 rounded font-black text-[0.45rem] uppercase">Comm: 25%</div>
           </div>
         </div>
       ))}
    </div>
  );

  const StepKYC = () => (
    <div className="space-y-4 animate-fade-in">
       <div className="relative aspect-[16/9] bg-gray-100 dark:bg-white/5 rounded-2xl border-2 border-dashed border-primary-500/30 flex flex-col items-center justify-center overflow-hidden cursor-pointer group">
          {kycData.photo ? <img src={kycData.photo} className="w-full h-full object-cover"/> : (
            <>
              <Camera size={32} className="text-primary-500 mb-2 group-hover:scale-110 transition-transform"/>
              <p className="text-[0.6rem] font-black uppercase text-gray-400">Scan KTP Nasabah</p>
              <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleKtpUpload} />
            </>
          )}
          {loading && <div className="absolute inset-0 bg-black/40 flex items-center justify-center text-white"><Loader2 className="animate-spin" /></div>}
       </div>
       <div className="grid grid-cols-2 gap-2">
          <input placeholder="Nama Lengkap" value={kycData.name} className="p-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-xs font-bold" onChange={(e) => setKycData({...kycData, name: e.target.value})}/>
          <input placeholder="Nomor KTP" value={kycData.ktp} className="p-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-xs font-bold" onChange={(e) => setKycData({...kycData, ktp: e.target.value})}/>
          <input placeholder="Email" value={kycData.email} className="p-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-xs font-bold" onChange={(e) => setKycData({...kycData, email: e.target.value})}/>
          <input placeholder="Nomor HP" value={kycData.phone} className="p-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-xs font-bold" onChange={(e) => setKycData({...kycData, phone: e.target.value})}/>
       </div>
    </div>
  );

  const StepSurvey = () => (
    <div className="space-y-4 animate-fade-in">
       <div className="p-3 bg-gray-900 text-white rounded-xl flex items-center justify-between">
          <div className="flex items-center gap-3">
            <ShieldCheck size={20} className="text-primary-500"/>
            <div>
              <p className="text-[0.45rem] font-black uppercase text-gray-400">AI Scoring Confidence</p>
              <p className="text-xl font-black">{survey.score}%</p>
            </div>
          </div>
          {survey.score > 0 && (
            <div className={`px-3 py-1 rounded-full text-[0.6rem] font-black uppercase ${survey.score >= 80 ? 'bg-emerald-500' : 'bg-amber-500'}`}>
              {survey.score >= 80 ? 'APPROVED' : 'MANUAL VERIF REQ'}
            </div>
          )}
       </div>

       <div className="grid grid-cols-3 gap-2">
          <div className="aspect-square bg-gray-100 dark:bg-white/5 rounded-xl flex flex-col items-center justify-center border border-black/5 relative overflow-hidden group">
            {survey.stnk ? <img src={survey.stnk} className="w-full h-full object-cover"/> : <><Smartphone size={16}/><p className="text-[0.4rem] font-bold uppercase mt-1">STNK</p><input type="file" className="absolute inset-0 opacity-0" onChange={handleStnkUpload}/></>}
          </div>
          {[1,2,3,4,5].map(i => (
            <div key={i} className="aspect-square bg-gray-100 dark:bg-white/5 rounded-xl flex flex-col items-center justify-center border border-black/5 relative overflow-hidden group">
               <ImageIcon size={16} className="text-gray-400"/>
               <p className="text-[0.4rem] font-bold uppercase mt-1">Side {i}</p>
               <input type="file" className="absolute inset-0 opacity-0" onChange={(e) => {
                 const file = e.target.files[0];
                 const reader = new FileReader();
                 reader.onload = () => setSurvey(prev => ({ ...prev, photos: [...prev.photos, reader.result as string] }));
                 reader.readAsDataURL(file);
               }}/>
            </div>
          ))}
       </div>

       <button 
         onClick={runSurveyAI}
         disabled={survey.photos.length < 5 || loading}
         className="w-full py-4 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.6rem] tracking-widest shadow-xl flex items-center justify-center gap-2 disabled:opacity-50"
       >
         {loading ? <Loader2 className="animate-spin" size={16}/> : <Zap size={16}/>}
         Run Neural Audit
       </button>
    </div>
  );

  const StepFinal = () => (
    <div className="space-y-4 animate-fade-in">
       <div className="p-4 bg-white dark:bg-white/5 rounded-2xl border border-black/5 space-y-3">
          <div className="flex justify-between items-start">
             <div>
               <p className="text-[0.45rem] font-black uppercase text-gray-400">Summary Order</p>
               <h4 className="text-lg font-black uppercase tracking-tight">{kycData.name}</h4>
             </div>
             <button onClick={() => window.print()} className="p-2 bg-gray-100 dark:bg-white/10 rounded-lg text-gray-500"><Printer size={16}/></button>
          </div>
          <div className="grid grid-cols-2 gap-y-2 text-[0.6rem] border-t border-black/5 pt-3">
             <span className="text-gray-400 font-bold uppercase">Unit:</span> <span className="font-black text-right">{vehicle.brand} {vehicle.model}</span>
             <span className="text-gray-400 font-bold uppercase">Plat:</span> <span className="font-black text-right">{vehicle.plate}</span>
             <span className="text-gray-400 font-bold uppercase">Polis:</span> <span className="font-black text-right text-primary-500">{coverage.type}</span>
          </div>
       </div>

       <div className="space-y-2">
          <p className="text-[0.6rem] font-black uppercase text-gray-400 ml-2">Metode Kirim Polis</p>
          <div className="grid grid-cols-3 gap-2">
             {['WHATSAPP', 'EMAIL', 'HARDCOPY'].map(m => (
               <button 
                 key={m} 
                 onClick={() => setDelivery({...delivery, method: m})}
                 className={`py-2 rounded-lg text-[0.5rem] font-black transition-all ${delivery.method === m ? 'bg-primary-500 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-400'}`}
               >{m}</button>
             ))}
          </div>
          {delivery.method === 'HARDCOPY' && (
            <textarea 
              placeholder="Alamat Pengiriman & Penerima" 
              className="w-full p-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-xs font-bold"
              onChange={(e) => setDelivery({...delivery, address: e.target.value})}
            />
          )}
       </div>

       <button 
         onClick={onComplete}
         className="w-full py-5 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-sm tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 transition-all active:scale-95"
       >
         <Coins size={20}/>
         Bayar {formatIDR(calculatedPremium + (providerDetails.find(p => p.id === selectedProvider)?.fee || 0) + STAMP_DUTY)}
       </button>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white rounded-[2.5rem] overflow-hidden border border-black/5 shadow-2xl">
       {/* Header Navigation */}
       <div className="p-6 bg-white dark:bg-white/5 border-b border-black/5 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-8 h-8 bg-primary-500 rounded-lg flex items-center justify-center text-white"><Car size={18}/></div>
             <div>
                <p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-widest leading-none">Auto Insurance</p>
                <h3 className="text-sm font-black uppercase tracking-tighter">Beli Polis Baru</h3>
             </div>
          </div>
          <div className="flex gap-1.5">
             {STEPS.map((s, i) => (
               <div key={s.id} className={`h-1 rounded-full transition-all ${i === step ? 'w-6 bg-primary-500' : i < step ? 'w-2 bg-primary-500/40' : 'w-2 bg-gray-200 dark:bg-white/10'}`}></div>
             ))}
          </div>
       </div>

       {/* Step Content */}
       <div className="flex-1 overflow-y-auto p-6 no-scrollbar">
          {step === 0 && <StepVehicle />}
          {step === 1 && <StepCoverage />}
          {step === 2 && <StepProviders />}
          {step === 3 && <StepKYC />}
          {step === 4 && <StepSurvey />}
          {step === 5 && <StepFinal />}
       </div>

       {/* Sticky Premium Summary */}
       <div className="p-6 bg-white dark:bg-[#111] border-t border-black/5 space-y-4">
          <div className="flex justify-between items-end">
             <div>
                <p className="text-[0.5rem] font-black uppercase text-gray-400 leading-none mb-1">Estimasi Premi Tahunan</p>
                <p className="text-2xl font-black tracking-tighter text-primary-500">{formatIDR(calculatedPremium)}</p>
             </div>
             <div className="flex gap-2">
                {step > 0 && <button onClick={handleBack} className="p-3 bg-gray-100 dark:bg-white/10 rounded-xl text-gray-400"><ChevronRight className="rotate-180" size={20}/></button>}
                <button 
                  onClick={handleNext} 
                  disabled={step === STEPS.length - 1 || (step === 2 && !selectedProvider) || (step === 4 && survey.score < 80 && !survey.manualVerif)}
                  className="px-8 py-3 bg-gray-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.6rem] tracking-widest shadow-xl flex items-center gap-2"
                >
                  Lanjut <ChevronRight size={14}/>
                </button>
             </div>
          </div>
       </div>
    </div>
  );
};

export default CarInsuranceWizard;

import React, { useState, useMemo } from 'react';
import { 
  Car, Shield, Zap, ChevronRight, MapPin, Camera, 
  CheckCircle2, AlertCircle, Loader2, FileSearch, 
  Trash2, ShieldCheck, Info, 
  Wallet, Star, Smartphone, CloudRain, Mail, Phone, 
  Printer, Coins, Percent, Building, Image as ImageIcon
} from 'lucide-react';
import { CAR_DATABASE, getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS } from '../constants';
import { extractKtpData, extractStnkData, analyzeVehicleSurvey } from '../services/geminiService';
import { InsuranceType } from '../types';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const STEPS = [
  { id: 'VEHICLE', label: 'Unit' },
  { id: 'COVERAGE', label: 'Polis' },
  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'SURVEY', label: 'Verif' },
  { id: 'FINAL', label: 'Bayar' }
];

const CarInsuranceWizard = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);

  // State Management
  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2024, isOther: false, 
    price: 0, manualPrice: false, plate: '', 
    region: '3' as '1'|'2'|'3', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProvider, setSelectedProvider] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ name: '', ktp: '', address: '', email: '', phone: '', photo: null as string|null });
  const [survey, setSurvey] = useState({ stnk: null as string|null, photos: [] as string[], score: 0, manualVerif: false });
  const [delivery, setDelivery] = useState({ method: 'EMAIL', address: '', recipient: '' });

  // Calculations
  const calculatedPremium = useMemo(() => {
    if (!vehicle.price) return 0;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    let totalRate = baseRate;

    if (coverage.authorized) totalRate += AUTHORIZED_WORKSHOP_RATE;
    if (coverage.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (coverage.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) totalRate += srccRate;

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) totalRate += tsRate;

    let prem = (vehicle.price * totalRate) / 100;

    if (coverage.tpl > 0) prem += coverage.tpl * 0.001; 

    let discVal = coverage.discount;
    if (coverage.discountType === 'PERCENT') {
        discVal = Math.min(coverage.discount, 25);
        prem = prem * (1 - discVal/100);
    } else {
        prem = Math.max(prem - discVal, prem * 0.75); 
    }

    return Math.round(prem);
  }, [vehicle, coverage]);

  const providerDetails = [
    { id: 'intra', name: 'Intra Asia', fee: 30000, coins: 0.15, pros: ['Termurah', 'Cepat'], cons: ['Banyak Pengecualian'] },
    { id: 'zurich', name: 'Zurich', fee: 55000, coins: 0.10, pros: ['Global Standard', 'Premium'], cons: ['Admin Mahal'] },
    { id: 'tugu', name: 'Tugu Insurance', fee: 50000, coins: 0.10, pros: ['BUMN Group', 'Aman'], cons: ['Proses Kaku'] }
  ];

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const handleKtpUpload = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const res = await extractKtpData(base64);
      if (res.success) setKycData(prev => ({ ...prev, ...res.data, photo: base64 }));
      setLoading(false);
    };
    reader.readAsDataURL(file);
  };

  const handleStnkUpload = async (e: any) => {
    const file = e.target.files[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const res = await extractStnkData(base64);
      if (res.success) setSurvey(prev => ({ ...prev, stnk: base64 }));
      setLoading(false);
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    setLoading(true);
    const res = await analyzeVehicleSurvey(survey.photos);
    if (res.success) setSurvey(prev => ({ ...prev, score: res.score || 0 }));
    setLoading(false);
  };

  // Render Helpers (Returning JSX directly instead of being functional components to avoid focus loss)
  const renderStepVehicle = () => (
    <div className="space-y-4 animate-fade-in">
      <div className="grid grid-cols-2 gap-3">
        <div className="col-span-2 space-y-1">
          <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2">Merk & Model</label>
          <div className="flex gap-2">
            <select 
              className="flex-1 p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 outline-none focus:border-primary-500 font-bold text-xs"
              value={vehicle.isOther ? 'OTHER' : vehicle.brand}
              onChange={(e) => {
                const val = e.target.value;
                if (val === 'OTHER') setVehicle({...vehicle, isOther: true, brand: '', model: ''});
                else {
                  const unit = CAR_DATABASE.find(c => c.brand === val);
                  setVehicle({...vehicle, isOther: false, brand: val, model: unit?.modelName || '', price: (unit?.yearPrices[2024] || 0) * 1000000});
                }
              }}
            >
              <option value="">Pilih Merk</option>
              {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b}>{b}</option>)}
              <option value="OTHER">OTHERS (Freetype)</option>
            </select>
            {vehicle.isOther && (
              <input 
                placeholder="Model Manual"
                value={vehicle.model}
                className="flex-1 p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 outline-none focus:border-primary-500 font-bold text-xs"
                onChange={(e) => setVehicle({...vehicle, model: e.target.value})}
              />
            )}
          </div>
        </div>

        <div className="space-y-1">
          <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2">Harga Unit</label>
          <input 
            type="number"
            className="w-full p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 outline-none focus:border-primary-500 font-black text-xs text-primary-500"
            value={vehicle.price}
            onChange={(e) => setVehicle({...vehicle, price: Number(e.target.value), manualPrice: true})}
          />
        </div>

        <div className="space-y-1">
          <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2">Nomor Plat</label>
          <input 
            placeholder="AA-1234-XYZ"
            className="w-full p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 outline-none focus:border-primary-500 font-black text-xs tracking-widest uppercase"
            value={vehicle.plate}
            onChange={(e) => {
              const val = e.target.value.toUpperCase();
              const prefix = val.split('-')[0];
              const region = PLATE_REGIONS[prefix] || '3';
              setVehicle({...vehicle, plate: val, region});
            }}
          />
        </div>
      </div>

      <div className="p-3 bg-primary-500/5 border border-primary-500/10 rounded-xl flex items-center gap-3">
        <MapPin size={16} className="text-primary-500"/>
        <div>
          <p className="text-[0.5rem] font-black uppercase text-gray-400 leading-none">OJK Territory</p>
          <p className="text-[0.6rem] font-bold">Region {vehicle.region}: {vehicle.region === '1' ? 'Sumatera' : vehicle.region === '2' ? 'DKI/Jabar/Banten' : 'Lainnya'}</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2">
         {['PRIVATE', 'COMMERCIAL', 'DINAS'].map(u => (
           <button 
             key={u}
             onClick={() => setVehicle({...vehicle, usage: u as any})}
             className={`py-2 rounded-lg text-[0.55rem] font-black uppercase tracking-widest transition-all ${vehicle.usage === u ? 'bg-primary-500 text-white shadow-lg' : 'bg-gray-100 dark:bg-white/5 text-gray-400'}`}
           >{u}</button>
         ))}
      </div>
    </div>
  );

  const renderStepCoverage = () => (
    <div className="space-y-3 animate-fade-in">
       <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl">
          {([InsuranceType.COMPREHENSIVE, InsuranceType.TLO]).map(t => (
            <button 
              key={t}
              onClick={() => setCoverage({...coverage, type: t})}
              className={`flex-1 py-2 rounded-lg text-[0.6rem] font-black uppercase transition-all ${coverage.type === t ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-sm' : 'text-gray-400'}`}
            >{t}</button>
          ))}
       </div>

       <div className="grid grid-cols-2 gap-2">
          {[
            { id: 'authorized', label: 'Bengkel Authorized (+0.2%)', icon: Building },
            { id: 'flood', label: 'Banjir & Angin Ribut', icon: CloudRain },
            { id: 'earthquake', label: 'Gempa & Tsunami', icon: Zap },
            { id: 'srcc', label: 'SRCC (Huru Hara)', icon: AlertCircle },
          ].map(opt => (
            <button 
              key={opt.id}
              onClick={() => setCoverage({...coverage, [opt.id]: !coverage[opt.id as keyof typeof coverage]})}
              className={`p-3 rounded-xl border text-left flex items-start gap-2 transition-all ${coverage[opt.id as keyof typeof coverage] ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5 opacity-60'}`}
            >
              <opt.icon size={14} className={coverage[opt.id as keyof typeof coverage] ? 'text-primary-500' : 'text-gray-400'}/>
              <span className="text-[0.5rem] font-black uppercase leading-tight">{opt.label}</span>
            </button>
          ))}
       </div>

       <div className="p-3 bg-gray-100 dark:bg-white/5 rounded-xl space-y-2">
          <div className="flex justify-between items-center">
            <span className="text-[0.6rem] font-black uppercase text-gray-500">Promo & Discount</span>
            <span className="text-[0.5rem] text-primary-500 font-bold uppercase">Max 25% Benefit</span>
          </div>
          <div className="flex gap-2">
            <input 
              placeholder="Voucher Code" 
              className="flex-1 p-2 rounded-lg bg-white dark:bg-white/10 text-xs font-bold border border-black/5 uppercase"
              value={coverage.promo}
              onChange={(e) => setCoverage({...coverage, promo: e.target.value})}
            />
            <input 
              type="number" placeholder="Value" 
              className="w-20 p-2 rounded-lg bg-white dark:bg-white/10 text-xs font-black text-primary-500 border border-black/5"
              value={coverage.discount}
              onChange={(e) => setCoverage({...coverage, discount: Number(e.target.value)})}
            />
            <select 
              className="p-2 rounded-lg bg-white dark:bg-white/10 text-[0.6rem] font-black uppercase border border-black/5"
              value={coverage.discountType}
              onChange={(e) => setCoverage({...coverage, discountType: e.target.value as any})}
            >
              <option value="NOMINAL">IDR</option>
              <option value="PERCENT">%</option>
            </select>
          </div>
       </div>
    </div>
  );

  const renderStepProviders = () => (
    <div className="space-y-2 animate-fade-in">
       {providerDetails.map(p => (
         <div 
           key={p.id} 
           onClick={() => setSelectedProvider(p.id)}
