              checked={reportForm.thirdPartyInvolved}
              onChange={(e) => setReportForm({...reportForm, thirdPartyInvolved: e.target.checked})}
            />
          </div>
        </form>

        <button 
          onClick={handleFinalReport} disabled={isSubmitting}
          className="mt-2 w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.55rem] tracking-[0.2em] shadow-xl flex items-center justify-center gap-2 disabled:opacity-50 transition-all active:scale-95"
        >
          {isSubmitting ? <Loader2 className="animate-spin" size={14}/> : <CheckCircle2 size={14}/>}
          Kirim Laporan Neural
        </button>
      </div>
    );
  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-4 py-4 animate-pop-in flex flex-col h-full justify-center">
        <div className="w-20 h-20 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl shadow-emerald-500/30">
          <CheckCircle2 size={40} strokeWidth={3} />
        </div>
        <div className="space-y-1">
          <h3 className="text-xl font-black uppercase tracking-tighter">Klaim <span className="text-primary-500">Tersubmit</span></h3>
          <p className="text-[0.55rem] text-gray-500 dark:text-gray-400 px-4 leading-relaxed font-bold uppercase tracking-widest">
            Sistem Neural OS sedang memproses verifikasi akhir. Konfirmasi payout akan dikirim dalam <span className="text-primary-500">60 detik</span>.
          </p>
        </div>
        <div className="p-3 rounded-xl bg-gray-100 dark:bg-white/5 border border-black/5 text-left">
          <p className="text-[0.4rem] font-black text-gray-400 uppercase tracking-widest mb-0.5">Reference Hash</p>
          <p className="text-[0.55rem] font-mono text-primary-500 break-all leading-tight">SP-NRL-{Date.now().toString().slice(-8)}</p>
        </div>
        <button onClick={onComplete} className="w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.5rem] tracking-widest shadow-xl transition-all active:scale-95">Back to Portal</button>
      </div>
    );
  }

  return null;
};

