            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Nomor Plat Polisi</label>
            <div className="relative h-[68px] rounded-2xl bg-[#111] border-2 border-[#333] p-1 flex items-center justify-center overflow-hidden shadow-[inset_0_2px_10px_rgba(0,0,0,0.5)] group">
