import { CAR_DATABASE, getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS } from '../constants';
import { extractKtpData, extractStnkData, analyzeVehicleSurvey } from '../services/geminiService';
import { InsuranceType } from '../types';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const STEPS = [
  { id: 'VEHICLE', label: 'Unit' },
  { id: 'COVERAGE', label: 'Polis' },
  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'SURVEY', label: 'Verif' },
  { id: 'REVIEW', label: 'Rincian' }, // New Review Step
  { id: 'FINAL', label: 'Bayar' }
];

const CarInsuranceWizard = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);

  // State Management
  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2024, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProvider, setSelectedProvider] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ name: '', ktp: '', address: '', email: '', phone: '', photo: null as string|null });
  const [survey, setSurvey] = useState({ stnk: null as string|null, photos: [] as string[], score: 0, manualVerif: false });
  const [delivery, setDelivery] = useState({ method: 'EMAIL', address: '', recipient: '' });

  // Calculations
  const calculatedPremium = useMemo(() => {
    if (!vehicle.price) return 0;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    let totalRate = baseRate;

    if (coverage.authorized) totalRate += AUTHORIZED_WORKSHOP_RATE;
    if (coverage.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (coverage.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) totalRate += srccRate;

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) totalRate += tsRate;

    let prem = (vehicle.price * totalRate) / 100;
    if (coverage.tpl > 0) prem += coverage.tpl * 0.001; 

    let discVal = coverage.discount;
    if (coverage.discountType === 'PERCENT') {
        discVal = Math.min(coverage.discount, 25);
        prem = prem * (1 - discVal/100);
    } else {
        prem = Math.max(prem - discVal, prem * 0.75); 
    }

    return Math.round(prem);
  }, [vehicle, coverage]);

  const providerDetails = [
    { id: 'intra', name: 'Intra Asia', fee: 30000, coins: 0.15, pros: ['Termurah', 'Cepat'], cons: ['Banyak Pengecualian'] },
    { id: 'zurich', name: 'Zurich', fee: 55000, coins: 0.10, pros: ['Global Standard', 'Premium'], cons: ['Admin Mahal'] },
    { id: 'tugu', name: 'Tugu Insurance', fee: 50000, coins: 0.10, pros: ['BUMN Group', 'Aman'], cons: ['Proses Kaku'] }
  ];

  const currentProvider = useMemo(() => providerDetails.find(p => p.id === selectedProvider), [selectedProvider]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  // UX Helpers
  const formatInputCurrency = (value: string) => {
    const numeric = value.replace(/\D/g, "");
    if (!numeric) return "";
    return new Intl.NumberFormat('id-ID').format(parseInt(numeric));
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase();
    val = val.replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({
        ...vehicle, 
        plate, 
        region: regionInfo?.region || '3', 
        regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)'
      });
    } else {
      setVehicle({...vehicle, plate: val});
    }
  };

  const isPriceInvalid = useMemo(() => {
    if (!vehicle.manualPrice || vehicle.basePrice === 0) return false;
    const min = vehicle.basePrice * 0.9;
    const max = vehicle.basePrice * 1.1;
    return vehicle.price < min || vehicle.price > max;
  }, [vehicle.price, vehicle.basePrice, vehicle.manualPrice]);

  const handleKtpUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setKycData(prev => ({ ...prev, photo: base64 }));
      const response = await extractKtpData(base64);
      setLoading(false);
      if (response.success && response.data) {
        setKycData(prev => ({
          ...prev,
          name: response.data.name || response.data.Name || prev.name,
          ktp: response.data.ktpNumber || response.data.ktp || response.data["KTP Number"] || prev.ktp,
          address: response.data.address || response.data.Address || prev.address
        }));
      }
    };
    reader.readAsDataURL(file);
  };

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey(prev => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      if (response.success && response.data) {
        const extractedPlate = response.data.plate || response.data.Plate || response.data.PlateNo;
        if (extractedPlate) {
          setVehicle(prev => ({ ...prev, plate: extractedPlate }));
        }
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    if (survey.photos.length < 5) return;
    setLoading(true);
    const response = await analyzeVehicleSurvey(survey.photos);
    setLoading(false);
    if (response.success) {
      const score = response.score || 0;
      setSurvey(prev => ({ 
        ...prev, 
        score,
        manualVerif: score < 80 
      }));
      if (score < 80) {
        alert("Skor verifikasi rendah. Mohon pastikan foto jelas atau lanjutkan untuk review manual.");
      }
    } else {
      alert("Gagal melakukan audit neural.");
    }
  };

  const deleteSurveyPhoto = (index: number) => {
    setSurvey(prev => {
        const newPhotos = [...prev.photos];
        newPhotos.splice(index, 1);
        return { ...prev, photos: newPhotos };
    });
  };

  const renderStepVehicle = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="space-y-4">
        {/* Brand, Model & Year */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Merk Kendaraan</label>
            <div className="relative group">
              <select 
                className="w-full p-4 rounded-2xl bg-white dark:bg-gray-800 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-gray-900 dark:text-white"
                value={vehicle.isOther ? 'OTHER' : vehicle.brand}
                onChange={(e) => {
                  const val = e.target.value;
                  if (val === 'OTHER') setVehicle({...vehicle, isOther: true, brand: '', model: '', basePrice: 0});
                  else {
                    const unit = CAR_DATABASE.find(c => c.brand === val);
                    const p = (unit?.yearPrices[2024] || 0) * 1000000;
                    setVehicle({...vehicle, isOther: false, brand: val, model: unit?.modelName || '', price: p, basePrice: p});
                  }
                }}
              >
                <option value="" className="text-gray-900">Pilih Merk</option>
                {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b} className="text-gray-900">{b}</option>)}
                <option value="OTHER" className="text-gray-900">Lainnya / Freetype</option>
              </select>
              <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400 group-hover:text-primary-500 transition-colors">
                <ChevronRight className="rotate-90" size={18}/>
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Tipe Model</label>
            <div className="relative">
                <input 
                readOnly={!vehicle.isOther}
                placeholder={vehicle.brand ? `Model ${vehicle.brand}` : "Pilih Merk Dahulu"}
                value={vehicle.model}
                className={`w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm transition-all ${!vehicle.isOther ? 'bg-gray-50 dark:bg-black/20 text-gray-400 cursor-not-allowed' : 'text-primary-500 dark:text-white'}`}
                onChange={(e) => setVehicle({...vehicle, model: e.target.value})}
                />
                {!vehicle.isOther && vehicle.brand && <div className="absolute right-4 top-1/2 -translate-y-1/2 text-primary-500/30"><UserCheck size={16}/></div>}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Tahun Pembuatan</label>
            <div className="relative group">
              <select 
                className="w-full p-4 rounded-2xl bg-white dark:bg-gray-800 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-gray-900 dark:text-white"
                value={vehicle.year}
                onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}
              >
                {Array.from({length: 16}, (_, i) => 2025 - i).map(year => (
                  <option key={year} value={year} className="text-gray-900">{year}</option>
                ))}
              </select>
              <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                <Calendar size={18}/>
              </div>
            </div>
          </div>
        </div>

        {/* Price & Plate UI */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <div className="flex justify-between items-center ml-1">
              <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-[0.1em]">Harga Pasar (OTR)</label>
              {vehicle.basePrice > 0 && <span className="text-[0.45rem] font-black text-primary-500 bg-primary-500/10 px-2 py-0.5 rounded">AUTO-RANGE ±10%</span>}
            </div>
            <div className="relative group">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 font-black text-gray-400 text-sm">Rp</span>
              <input 
                type="text"
                inputMode="numeric"
                className={`w-full pl-11 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 outline-none font-black text-lg transition-all ${isPriceInvalid ? 'border-rose-500 text-rose-500 shadow-lg shadow-rose-500/10' : 'border-black/5 focus:border-primary-500 text-primary-500 group-hover:border-black/10'}`}
                value={formatInputCurrency(vehicle.price.toString())}
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, "");
                  setVehicle({...vehicle, price: parseInt(val || "0"), manualPrice: true});
                }}
              />
              {isPriceInvalid && (
                <div className="flex items-center gap-1.5 mt-1.5 text-[0.6rem] font-bold text-rose-500 bg-rose-500/5 p-2 rounded-lg animate-fade-in border border-rose-500/10">
                  <AlertCircle size={12}/> Allowed: {formatIDR(vehicle.basePrice * 0.9)} - {formatIDR(vehicle.basePrice * 1.1)}
                </div>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Nomor Plat Polisi</label>
            <div className="relative h-[68px] rounded-2xl bg-[#111] border-2 border-[#333] p-1 flex items-center justify-center overflow-hidden shadow-[inset_0_2px_10px_rgba(0,0,0,0.5)] group">
               <div className="absolute inset-0 bg-gradient-to-b from-white/5 to-transparent pointer-events-none"></div>
               <input 
                 placeholder="B 1234 XYZ"
                 maxLength={12}
                 className="w-full bg-transparent text-center font-black text-2xl tracking-[0.25em] text-white uppercase outline-none placeholder:text-gray-800 drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]"
                 value={vehicle.plate}
                 onChange={handlePlateChange}
               />
               <div className="absolute bottom-1 right-4 text-[0.4rem] font-black text-white/20 tracking-[0.4em] uppercase">NEURAL OS PLATE</div>
            </div>
            <div className="flex items-center gap-2 mt-1 ml-1">
              <div className="w-1.5 h-1.5 rounded-full bg-primary-500 animate-pulse"></div>
              <span className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest">{vehicle.regionName}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Usage Selection - Card Layout */}
      <div className="space-y-4">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.15em]">Tujuan Penggunaan & Kondisi</label>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="grid grid-cols-3 gap-2">
                {[
                    { id: 'PRIVATE', icon: User, label: 'Pribadi' },
                    { id: 'COMMERCIAL', icon: Briefcase, label: 'Komersial' },
                    { id: 'DINAS', icon: Building2, label: 'Dinas' }
                ].map(u => (
                    <button 
                        key={u.id}
                        type="button"
                        onClick={() => setVehicle({...vehicle, usage: u.id as any})}
                        className={`p-3 rounded-[1.5rem] border-2 flex flex-col items-center text-center gap-1.5 transition-all relative overflow-hidden ${vehicle.usage === u.id ? 'border-primary-500 bg-primary-500/5 ring-4 ring-primary-500/5 shadow-lg scale-[1.02]' : 'border-black/5 bg-white dark:bg-white/5 hover:border-black/10'}`}
                    >
                        <u.icon size={20} className={vehicle.usage === u.id ? 'text-primary-500' : 'text-gray-400'}/>
                        <span className={`text-[0.55rem] font-black uppercase tracking-tighter ${vehicle.usage === u.id ? 'text-primary-600' : 'text-gray-500'}`}>{u.label}</span>
                    </button>
                ))}
            </div>

            <div className="grid grid-cols-2 gap-2">
                {[
                    { id: 'NEW', icon: Zap, label: 'Baru' },
                    { id: 'USED', icon: Timer, label: 'Second' }
                ].map(c => (
                    <button 
                        key={c.id}
                        type="button"
                        onClick={() => {
                            console.log("Setting condition to:", c.id);
                            setVehicle(v => ({...v, condition: c.id as any}));
                        }}
                        className={`p-3 rounded-[1.5rem] border-2 flex flex-col items-center text-center gap-1.5 transition-all relative overflow-hidden ${vehicle.condition === c.id ? 'border-primary-500 bg-primary-500/5 ring-4 ring-primary-500/5 shadow-lg scale-[1.02]' : 'border-black/5 bg-white dark:bg-white/5 hover:border-black/10'}`}
                    >
                        <c.icon size={20} className={vehicle.condition === c.id ? 'text-primary-500' : 'text-gray-400'}/>
                        <span className={`text-[0.55rem] font-black uppercase tracking-tighter ${vehicle.condition === c.id ? 'text-primary-600' : 'text-gray-500'}`}>{c.label}</span>
                    </button>
                ))}
            </div>
        </div>
      </div>
    </div>
  );

  const renderStepCoverage = () => (
    <div className="space-y-4 animate-fade-in">
       <div className="p-1 bg-gray-100 dark:bg-white/5 rounded-2xl flex gap-1">
          {([InsuranceType.COMPREHENSIVE, InsuranceType.TLO]).map(t => (
            <button 
              key={t}
              onClick={() => setCoverage({...coverage, type: t})}
              className={`flex-1 py-4 rounded-xl text-[0.7rem] font-black uppercase transition-all flex flex-col items-center gap-1 ${coverage.type === t ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-xl' : 'text-gray-400'}`}
            >
              {t}
              <span className="text-[0.45rem] font-bold opacity-60 tracking-normal capitalize">{t === 'COMPREHENSIVE' ? 'All Risk Protection' : 'Total Loss Only'}</span>
            </button>
          ))}
       </div>

       <div className="grid grid-cols-2 gap-2.5">
          {[
            { id: 'authorized', label: 'Bengkel Authorized (+0.2%)', icon: Building, desc: 'Perbaikan di dealer resmi.' },
            { id: 'flood', label: 'Banjir & Angin Ribut', icon: CloudRain, desc: 'Bencana alam hidrologi.' },
            { id: 'earthquake', label: 'Gempa & Tsunami', icon: Zap, desc: 'Bencana geologi dahsyat.' },
            { id: 'srcc', label: 'Huru Hara (SRCC)', icon: AlertCircle, desc: 'Kerusakan akibat kerusuhan.' },
          ].map(opt => (
            <button 
              key={opt.id}
              onClick={() => setCoverage({...coverage, [opt.id]: !coverage[opt.id as keyof typeof coverage]})}
              className={`p-4 rounded-2xl border-2 text-left flex flex-col gap-2 transition-all group ${coverage[opt.id as keyof typeof coverage] ? 'border-primary-500 bg-primary-500/5 ring-4 ring-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5 opacity-80'}`}
            >
              <div className="flex justify-between items-start">
                 <opt.icon size={20} className={coverage[opt.id as keyof typeof coverage] ? 'text-primary-500' : 'text-gray-300'}/>
                 {coverage[opt.id as keyof typeof coverage] && <CheckCircle2 size={16} className="text-primary-500"/>}
              </div>
              <div>
                <p className="text-[0.6rem] font-black uppercase leading-tight">{opt.label}</p>
                <p className="text-[0.45rem] font-bold text-gray-400 mt-1">{opt.desc}</p>
              </div>
            </button>
          ))}
       </div>

       <div className="p-5 bg-gray-900 text-white rounded-[2rem] space-y-4 shadow-2xl relative overflow-hidden">
          <div className="absolute right-0 top-0 p-8 opacity-10"><Percent size={120}/></div>
          <div className="flex justify-between items-center relative z-10">
            <div className="flex items-center gap-2">
               <Coins size={18} className="text-primary-400"/>
               <span className="text-[0.7rem] font-black uppercase tracking-widest">Neural Promo Engine</span>
            </div>
            <span className="text-[0.5rem] bg-primary-500 px-2 py-0.5 rounded font-black uppercase">Max 25% Disc</span>
          </div>
          <div className="flex gap-2 relative z-10">
            <input 
              placeholder="VOUCHER CODE" 
              className="flex-1 p-3 rounded-xl bg-white/10 text-xs font-black border border-white/10 uppercase placeholder:text-white/20 focus:bg-white/20 outline-none"
              value={coverage.promo}
              onChange={(e) => setCoverage({...coverage, promo: e.target.value})}
            />
            <div className="flex bg-white/10 rounded-xl p-1 items-center">
              <input 
                type="text" placeholder="Value" 
                className="w-20 bg-transparent text-center text-sm font-black text-primary-400 outline-none"
                value={coverage.discount === 0 ? "" : coverage.discount}
                onChange={(e) => {
                   const val = e.target.value.replace(/\D/g, "");
                   setCoverage({...coverage, discount: parseInt(val || "0")});
                }}
              />
              <select 
                className="bg-primary-500 text-white p-1.5 rounded-lg text-[0.6rem] font-black uppercase outline-none"
                value={coverage.discountType}
                onChange={(e) => setCoverage({...coverage, discountType: e.target.value as any})}
              >
                <option value="NOMINAL">IDR</option>
                <option value="PERCENT">%</option>
              </select>
            </div>
          </div>
       </div>
    </div>
  );

  const renderStepProviders = () => (
    <div className="space-y-3 animate-fade-in">
       <div className="flex justify-between items-end mb-2 ml-1">
          <div>
            <h4 className="text-sm font-black uppercase tracking-tight">Opsi Rekanan</h4>
            <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Berdasarkan Neural Scoring</p>
          </div>
       </div>
       {providerDetails.map(p => (
         <div 
           key={p.id} 
           onClick={() => setSelectedProvider(p.id)}
           className={`p-5 rounded-[2rem] border-2 cursor-pointer transition-all relative overflow-hidden group ${selectedProvider === p.id ? 'border-primary-500 bg-primary-500/5 ring-4 ring-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5 grayscale hover:grayscale-0'}`}
         >
           <div className="flex justify-between items-start mb-4">
              <div className="flex items-center gap-3">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg shadow-lg ${selectedProvider === p.id ? 'bg-primary-500 text-white' : 'bg-gray-100 dark:bg-white/10'}`}>
                  {p.name[0]}
                </div>
                <div>
                   <h4 className="font-black text-sm uppercase tracking-tight">{p.name}</h4>
                   <div className="flex gap-1">
                      {[1,2,3,4,5].map(i => <Star key={i} size={8} className="fill-amber-400 text-amber-400"/>)}
                   </div>
                </div>
              </div>
              <div className="text-right">
                <p className="text-lg font-black text-primary-500 leading-none">{formatIDR(calculatedPremium + p.fee + STAMP_DUTY)}</p>
                <p className="text-[0.45rem] text-gray-400 uppercase font-bold mt-1 tracking-widest">Total Premi Net</p>
              </div>
           </div>

           <div className="grid grid-cols-2 gap-3 border-t border-black/5 pt-4">
              <div className="space-y-1">
                 <p className="text-[0.45rem] font-black uppercase text-gray-400">Kelebihan</p>
                 {p.pros.slice(0, 1).map((pro, i) => <p key={i} className="text-[0.55rem] font-bold flex items-center gap-1"><Check size={10} className="text-emerald-500"/> {pro}</p>)}
              </div>
              <div className="space-y-1">
                 <p className="text-[0.45rem] font-black uppercase text-gray-400">Path Benefits</p>
                 <div className="flex gap-1.5">
                    <div className="px-2 py-0.5 bg-emerald-500/10 text-emerald-500 rounded font-black text-[0.45rem] uppercase">Coins {p.coins * 100}%</div>
                    <div className="px-2 py-0.5 bg-amber-500/10 text-amber-500 rounded font-black text-[0.45rem] uppercase">Comm 25%</div>
                 </div>
              </div>
           </div>

           {selectedProvider === p.id && (
              <div className="absolute top-0 right-0 p-4">
                 <div className="w-6 h-6 bg-primary-500 rounded-full flex items-center justify-center text-white shadow-lg animate-pop-in">
                    <Check size={14} strokeWidth={4}/>
                 </div>
              </div>
           )}
