                 <ChevronRight className="rotate-180" size={20}/>
               </button>
             )}
             <button 
               onClick={handleNext} 
               disabled={
                 step === STEPS.length - 1 || 
                 (step === 0 && (vehicle.price === 0 || vehicle.plate.length < 5)) ||
                 (step === 2 && !selectedProvider) || 
                 (step === 3 && !kycStepValid) ||
                 (step === 4 && !surveyStepValid)
               }
               className="flex-1 sm:flex-none px-8 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.6rem] tracking-[0.2em] shadow-xl transition-all active:scale-95 disabled:opacity-30 flex items-center justify-center gap-2"
             >
               Lanjutkan <ChevronRight size={16}/>
             </button>
          </div>
       </div>
    </div>
  );
};

