  Users2, AlertTriangle, FileUp, Download, Eye
} from 'lucide-react';
import { CAR_DATABASE, getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS, TPL_OPTIONS } from '../constants';
import { extractKtpData, extractStnkData, analyzeVehicleSurvey } from '../services/geminiService';
import { InsuranceType } from '../types';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);
const formatShortIDR = (n: number) => n >= 1000000 ? `${n / 1000000}jt` : n.toString();

const STEPS = [
  { id: 'VEHICLE', label: 'Unit' },
  { id: 'COVERAGE', label: 'Polis' },
  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'SURVEY', label: 'Verif' },
  { id: 'REVIEW', label: 'Rincian' },
  { id: 'FINAL', label: 'Summary' }
];

const CarInsuranceWizard = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const summaryRef = useRef<HTMLDivElement>(null);

  // State Management
  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2024, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProvider, setSelectedProvider] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ name: '', ktp: '', address: '', email: '', phone: '', photo: null as string|null });
  const [survey, setSurvey] = useState({ 
    stnk: null as string|null, 
    photos: [] as string[], 
    score: 0, 
    report: '',
    manualVerif: false,
    isManualSubmission: false
  });
  const [delivery, setDelivery] = useState({ method: 'EMAIL', address: '', recipient: '' });

  // Calculations
  const calculatedPremium = useMemo(() => {
    if (!vehicle.price) return 0;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    let totalRate = baseRate;

    if (coverage.authorized) totalRate += AUTHORIZED_WORKSHOP_RATE;
    if (coverage.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (coverage.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) totalRate += srccRate;

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) totalRate += tsRate;

    let prem = (vehicle.price * totalRate) / 100;
    if (coverage.tpl > 0) prem += (coverage.tpl * 0.001);

    let discVal = coverage.discount;
    if (coverage.discountType === 'PERCENT') {
        discVal = Math.min(coverage.discount, 25);
        prem = prem * (1 - discVal/100);
    } else {
        prem = Math.max(prem - discVal, prem * 0.75); 
    }

    return Math.round(prem);
  }, [vehicle, coverage]);

  const providerDetails = [
    { id: 'intra', name: 'Intra Asia', fee: 30000, coins: 0.15, pros: ['Termurah', 'Cepat'], cons: ['Banyak Pengecualian'] },
    { id: 'zurich', name: 'Zurich', fee: 55000, coins: 0.10, pros: ['Global Standard', 'Premium'], cons: ['Admin Mahal'] },
    { id: 'tugu', name: 'Tugu Insurance', fee: 50000, coins: 0.10, pros: ['BUMN Group', 'Aman'], cons: ['Proses Kaku'] }
  ];

  const currentProvider = useMemo(() => providerDetails.find(p => p.id === selectedProvider), [selectedProvider]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const handlePrint = () => {
    window.print();
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase();
    val = val.replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({
        ...vehicle, 
        plate, 
        region: regionInfo?.region || '3', 
        regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)'
      });
    } else {
      setVehicle({...vehicle, plate: val});
    }
  };

  const handleKtpUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await extractKtpData(base64);
      setLoading(false);
      if (response.success && response.data) {
        setKycData(prev => ({
          ...prev,
          name: response.data.name || response.data.Name || prev.name,
          ktp: response.data.ktp || response.data.KTPNumber || prev.ktp,
          address: response.data.address || response.data.Address || prev.address,
          photo: base64
        }));
      } else {
        setKycData(prev => ({ ...prev, photo: base64 }));
      }
    };
    reader.readAsDataURL(file);
  };

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await extractStnkData(base64);
      setLoading(false);
      if (response.success && response.data) {
        setSurvey(prev => ({ ...prev, stnk: base64 }));
      } else {
        setSurvey(prev => ({ ...prev, stnk: base64 }));
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    if (survey.photos.length < 5) return;
    setLoading(true);
    const response = await analyzeVehicleSurvey(survey.photos);
    setLoading(false);

    if (response.success) {
      const score = response.score || 0;
      setSurvey(prev => ({ 
        ...prev, 
        score,
        report: response.report || 'Audit selesai tanpa temuan mayor.',
        manualVerif: score < 85 // Threshold 85 as requested
      }));
    } else {
      alert("Gagal melakukan audit neural. Pastikan koneksi internet stabil.");
    }
  };

  const deleteSurveyPhoto = (index: number) => {
    setSurvey(prev => {
        const newPhotos = [...prev.photos];
        newPhotos.splice(index, 1);
        return { ...prev, photos: newPhotos };
    });
  };

  const renderStepVehicle = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Merk Kendaraan</label>
            <div className="relative group">
              <select 
                className="w-full p-4 rounded-2xl bg-white dark:bg-gray-800 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-gray-900 dark:text-white"
                value={vehicle.isOther ? 'OTHER' : vehicle.brand}
                onChange={(e) => {
                  const val = e.target.value;
                  if (val === 'OTHER') setVehicle({...vehicle, isOther: true, brand: '', model: '', basePrice: 0});
                  else {
                    const unit = CAR_DATABASE.find(c => c.brand === val);
                    const p = (unit?.yearPrices[2024] || 0) * 1000000;
                    setVehicle({...vehicle, isOther: false, brand: val, model: unit?.modelName || '', price: p, basePrice: p});
                  }
                }}
              >
                <option value="" className="text-gray-900">Pilih Merk</option>
                {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b} className="text-gray-900">{b}</option>)}
                <option value="OTHER" className="text-gray-900">Lainnya / Freetype</option>
              </select>
              <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400 group-hover:text-primary-500 transition-colors">
                <ChevronRight className="rotate-90" size={18}/>
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Tipe Model</label>
            <input 
              readOnly={!vehicle.isOther}
              placeholder={vehicle.brand ? `Model ${vehicle.brand}` : "Pilih Merk Dahulu"}
              value={vehicle.model}
              className={`w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm transition-all ${!vehicle.isOther ? 'bg-gray-50 dark:bg-black/20 text-gray-400 cursor-not-allowed' : 'text-primary-500 dark:text-white'}`}
              onChange={(e) => setVehicle({...vehicle, model: e.target.value})}
            />
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Tahun Pembuatan</label>
            <div className="relative group">
              <select 
                className="w-full p-4 rounded-2xl bg-white dark:bg-gray-800 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-gray-900 dark:text-white"
                value={vehicle.year}
                onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}
              >
                {Array.from({length: 16}, (_, i) => 2025 - i).map(year => (
                  <option key={year} value={year} className="text-gray-900">{year}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-[0.1em]">Harga Pasar (OTR)</label>
            <div className="relative group">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 font-black text-gray-400 text-sm">Rp</span>
              <input 
                type="text"
                className="w-full pl-11 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 focus:border-primary-500 outline-none font-black text-lg transition-all"
                value={new Intl.NumberFormat('id-ID').format(vehicle.price)}
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, "");
                  setVehicle({...vehicle, price: parseInt(val || "0"), manualPrice: true});
                }}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Nomor Plat Polisi</label>
            <div className="relative h-[68px] rounded-2xl bg-[#111] border-2 border-[#333] p-1 flex items-center justify-center shadow-inner">
               <input 
                 placeholder="B 1234 XYZ"
                 maxLength={12}
                 className="w-full bg-transparent text-center font-black text-2xl tracking-[0.25em] text-white uppercase outline-none placeholder:text-gray-800"
                 value={vehicle.plate}
                 onChange={handlePlateChange}
               />
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-4">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.15em]">Tujuan Penggunaan & Kondisi</label>
        <div className="grid grid-cols-2 gap-4">
            <div className="grid grid-cols-2 gap-2">
                {[{ id: 'PRIVATE', icon: User, label: 'Pribadi' }, { id: 'COMMERCIAL', icon: Briefcase, label: 'Komersial' }].map(u => (
                    <button 
                        key={u.id}
                        onClick={() => setVehicle({...vehicle, usage: u.id as any})}
                        className={`p-3 rounded-[1.5rem] border-2 flex flex-col items-center gap-1.5 transition-all ${vehicle.usage === u.id ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5'}`}
                    >
                        <u.icon size={20} className={vehicle.usage === u.id ? 'text-primary-500' : 'text-gray-400'}/>
                        <span className="text-[0.5rem] font-black uppercase">{u.label}</span>
                    </button>
                ))}
            </div>
            <div className="grid grid-cols-2 gap-2">
                {[{ id: 'NEW', icon: Zap, label: 'Baru' }, { id: 'USED', icon: Timer, label: 'Second' }].map(c => (
                    <button 
                        key={c.id}
                        onClick={() => setVehicle({...vehicle, condition: c.id as any})}
                        className={`p-3 rounded-[1.5rem] border-2 flex flex-col items-center gap-1.5 transition-all ${vehicle.condition === c.id ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5'}`}
                    >
                        <c.icon size={20} className={vehicle.condition === c.id ? 'text-primary-500' : 'text-gray-400'}/>
                        <span className="text-[0.5rem] font-black uppercase">{c.label}</span>
                    </button>
                ))}
            </div>
        </div>
      </div>
    </div>
  );

  const renderStepCoverage = () => (
    <div className="space-y-5 animate-fade-in">
       <div className="p-1 bg-gray-100 dark:bg-white/5 rounded-2xl flex gap-1">
          {([InsuranceType.COMPREHENSIVE, InsuranceType.TLO]).map(t => (
            <button 
              key={t}
              onClick={() => setCoverage({...coverage, type: t})}
              className={`flex-1 py-4 rounded-xl text-[0.7rem] font-black uppercase transition-all ${coverage.type === t ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-xl' : 'text-gray-400'}`}
            >
              {t}
            </button>
          ))}
       </div>

       <div className="space-y-2.5">
          <div className="flex items-center gap-2 ml-1">
             <Users2 size={16} className="text-primary-500"/>
             <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-[0.1em]">Limit TPL</label>
          </div>
          <div className="grid grid-cols-4 gap-2">
             {TPL_OPTIONS.map(opt => (
               <button 
                 key={opt}
                 onClick={() => setCoverage({...coverage, tpl: opt})}
                 className={`py-3 rounded-xl border-2 font-black text-[0.6rem] transition-all ${coverage.tpl === opt ? 'border-primary-500 bg-primary-500/5 text-primary-500' : 'border-black/5 bg-white dark:bg-white/5 text-gray-400'}`}
               >
                 {opt === 0 ? 'NONE' : formatShortIDR(opt)}
               </button>
             ))}
          </div>
       </div>

       <div className="grid grid-cols-2 gap-2.5">
          {[
            { id: 'authorized', label: 'Authorized', icon: Building },
            { id: 'flood', label: 'Banjir', icon: CloudRain },
            { id: 'earthquake', label: 'Gempa', icon: Zap },
            { id: 'srcc', label: 'Kerusuhan', icon: AlertCircle },
          ].map(opt => (
            <button 
              key={opt.id}
              onClick={() => setCoverage({...coverage, [opt.id]: !coverage[opt.id as keyof typeof coverage]})}
              className={`p-4 rounded-2xl border-2 text-left flex flex-col gap-2 transition-all ${coverage[opt.id as keyof typeof coverage] ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5 opacity-80'}`}
            >
              <opt.icon size={20} className={coverage[opt.id as keyof typeof coverage] ? 'text-primary-500' : 'text-gray-300'}/>
              <p className="text-[0.6rem] font-black uppercase leading-tight">{opt.label}</p>
            </button>
          ))}
       </div>
    </div>
  );

  const renderStepProviders = () => (
    <div className="space-y-4 animate-fade-in">
      <SectionHeader title="Pilih Penanggung" subtitle="Compare neural-rated providers" mini />
      <div className="space-y-3">
        {providerDetails.map(p => (
          <div 
            key={p.id}
            onClick={() => setSelectedProvider(p.id)}
            className={`p-5 rounded-[2rem] border-2 cursor-pointer transition-all ${selectedProvider === p.id ? 'border-primary-500 bg-primary-500/5 shadow-lg' : 'border-black/5 bg-white dark:bg-white/5 hover:border-black/10'}`}
          >
            <div className="flex justify-between items-start">
               <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-gray-100 dark:bg-white/10 rounded-xl flex items-center justify-center text-primary-500"><Building2 size={20}/></div>
                  <div>
                    <h4 className="font-black text-sm uppercase tracking-tight">{p.name}</h4>
                    <div className="flex items-center gap-1 mt-0.5">
                       <Star size={10} className="text-yellow-500 fill-yellow-500"/>
                       <span className="text-[0.5rem] font-black text-gray-400">4.8 RATIO</span>
                    </div>
                  </div>
               </div>
               <div className="text-right">
                  <p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-widest leading-none mb-1">Total Premi</p>
                  <p className="text-sm font-black text-primary-500 leading-none">{formatIDR(calculatedPremium + p.fee + STAMP_DUTY)}</p>
               </div>
            </div>
            <div className="mt-4 flex flex-wrap gap-2">
               {p.pros.map(pro => (
                 <span key={pro} className="px-2 py-0.5 rounded-md bg-emerald-500/10 text-emerald-500 text-[0.45rem] font-black uppercase tracking-widest">{pro}</span>
               ))}
               <div className="ml-auto flex items-center gap-1.5 text-primary-500">
                  <Coins size={12}/>
                  <span className="text-[0.55rem] font-black">+{p.coins * 100}% COINS</span>
               </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const renderStepKYC = () => (
    <div className="space-y-5 animate-fade-in">
       <div className="relative group">
          <div className={`relative aspect-[16/9] rounded-[2.5rem] border-4 border-dashed transition-all overflow-hidden flex flex-col items-center justify-center cursor-pointer ${kycData.photo ? 'border-primary-500/50' : 'border-black/5 bg-gray-50 dark:bg-white/5 hover:border-primary-500/30'}`}>
            {kycData.photo ? (
              <>
                <img src={kycData.photo} className="w-full h-full object-cover" alt="KTP"/>
                <button 
                    onClick={(e) => { e.stopPropagation(); setKycData({...kycData, photo: null}); }}
                    className="absolute top-4 right-4 p-2 bg-rose-500 text-white rounded-xl shadow-lg"
                >
                    <Trash2 size={16}/>
                </button>
              </>
            ) : (
              <>
                <ScanFace size={32} className="text-primary-500 mb-3"/>
                <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-[0.2em]">Scan KTP Anda</p>
                <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleKtpUpload} />
              </>
            )}
            {loading && <div className="absolute inset-0 bg-white/80 dark:bg-black/80 flex flex-col items-center justify-center gap-2 z-10"><Loader2 className="animate-spin text-primary-500" /><p className="text-[0.5rem] font-black uppercase tracking-widest text-primary-500">Neural OCR Analysis...</p></div>}
          </div>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-1.5">
             <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">Nama Sesuai KTP</label>
             <input placeholder="Nama Lengkap" value={kycData.name} className="w-full p-4 bg-white dark:bg-white/5 border-2 border-black/5 rounded-2xl text-xs font-bold focus:border-primary-500 outline-none" onChange={(e) => setKycData({...kycData, name: e.target.value})}/>
          </div>
          <div className="space-y-1.5">
             <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">NIK (16 Digit)</label>
             <input type="text" maxLength={16} placeholder="320..." value={kycData.ktp} className="w-full p-4 bg-white dark:bg-white/5 border-2 border-black/5 rounded-2xl text-xs font-bold focus:border-primary-500 outline-none" onChange={(e) => setKycData({...kycData, ktp: e.target.value.replace(/\D/g, "")})}/>
          </div>
          <div className="space-y-1.5">
             <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">Email</label>
             <input type="email" placeholder="name@email.com" value={kycData.email} className="w-full p-4 bg-white dark:bg-white/5 border-2 border-black/5 rounded-2xl text-xs font-bold focus:border-primary-500 outline-none" onChange={(e) => setKycData({...kycData, email: e.target.value})}/>
          </div>
          <div className="space-y-1.5">
             <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">WhatsApp</label>
             <input type="tel" placeholder="08..." value={kycData.phone} className="w-full p-4 bg-white dark:bg-white/5 border-2 border-black/5 rounded-2xl text-xs font-bold focus:border-primary-500 outline-none" onChange={(e) => setKycData({...kycData, phone: e.target.value})}/>
          </div>
       </div>
    </div>
  );

  const renderStepSurvey = () => (
    <div className="space-y-5 animate-fade-in h-full flex flex-col">
       <div className={`p-5 rounded-[2.5rem] flex items-center justify-between shadow-xl transition-colors ${survey.score === 0 ? 'bg-gray-900' : survey.score < 85 ? 'bg-rose-600' : 'bg-emerald-600'} text-white`}>
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center">
               <ShieldCheck size={24}/>
            </div>
            <div>
              <p className="text-[0.5rem] font-black uppercase opacity-60 tracking-widest">Neural Condition Score</p>
              <p className="text-2xl font-black">{survey.score > 0 ? `${survey.score}%` : '--'}</p>
            </div>
          </div>
          {survey.score > 0 && (
            <div className="px-4 py-1.5 rounded-full text-[0.6rem] font-black uppercase bg-white/20">
              {survey.score >= 85 ? 'Lulus Otomatis' : 'Gagal Otomatis'}
            </div>
          )}
       </div>

       {survey.score > 0 && survey.score < 85 && (
          <div className="p-4 bg-rose-50 dark:bg-rose-950/20 border border-rose-200 dark:border-rose-900/50 rounded-2xl space-y-2 animate-pop-in">
             <div className="flex items-center gap-2 text-rose-600 dark:text-rose-400">
                <AlertTriangle size={16}/>
                <p className="text-[0.65rem] font-black uppercase">Temuan Neural Audit</p>
             </div>
             <p className="text-[0.65rem] font-medium leading-relaxed italic">"{survey.report}"</p>
             <div className="pt-2 border-t border-rose-100 dark:border-rose-900/30">
                <button 
                  onClick={() => setSurvey({...survey, isManualSubmission: true, manualVerif: true})}
