    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);

    const basicPremium = (vehicle.price * baseRate) / 100;

    let expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Authorized', rate: AUTHORIZED_WORKSHOP_RATE, val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100 });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', rate: EXPANSION_RATES.FLOOD, val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100 });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', rate: EXPANSION_RATES.EARTHQUAKE, val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100 });

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', rate: srccRate, val: (vehicle.price * srccRate) / 100 });

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', rate: tsRate, val: (vehicle.price * tsRate) / 100 });

    const tplVal = coverage.tpl > 0 ? (coverage.tpl * 0.001) : 0; // Simple TPL rate logic
    if (coverage.tpl > 0) expansions.push({ name: 'TPL (Pihak Ke-3)', rate: 0.1, val: tplVal });

    const totalExpansion = expansions.reduce((acc, curr) => acc + curr.val, 0);
    const subtotal = basicPremium + totalExpansion;

    let discountVal = 0;
    if (coverage.discountType === 'PERCENT') {
        discountVal = (subtotal * Math.min(coverage.discount, 25)) / 100;
    } else {
        discountVal = Math.min(coverage.discount, subtotal * 0.25);
    }

    const netPremium = subtotal - discountVal;

    return {
        baseRate,
        basicPremium,
        expansions,
        discountVal,
        netPremium,
        adminFee: selectedProvider === 'zurich' ? 55000 : 50000,
        stampDuty: STAMP_DUTY
    };
  }, [vehicle, coverage, selectedProvider]);

