             <button onClick={() => window.print()} className="p-3 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-500 hover:text-primary-500 transition-colors"><Printer size={18}/></button>
          </div>

          <div className="grid grid-cols-1 gap-3 pt-4 border-t border-black/5 relative z-10">
             <div className="flex justify-between items-center text-[0.65rem]">
                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><Car size={12}/> Unit Kendaraan</span>
                <span className="font-black text-right">{vehicle.brand} {vehicle.model} ({vehicle.year})</span>
             </div>
             <div className="flex justify-between items-center text-[0.65rem]">
                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><Smartphone size={12}/> Nomor Plat</span>
                <span className="font-black text-right tracking-[0.1em]">{vehicle.plate}</span>
             </div>
             <div className="flex justify-between items-center text-[0.65rem]">
                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><Shield size={12}/> Jenis Polis</span>
                <span className="font-black text-right text-primary-500">{coverage.type}</span>
             </div>
          </div>
       </div>

       <div className="space-y-3">
          <label className="text-[0.65rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Pengiriman Dokumen Polis</label>
          <div className="grid grid-cols-3 gap-2">
             {[
               { id: 'WHATSAPP', icon: Smartphone },
               { id: 'EMAIL', icon: Mail },
               { id: 'HARDCOPY', icon: Building }
             ].map(m => (
               <button 
                 key={m.id} 
                 onClick={() => setDelivery({...delivery, method: m.id})}
                 className={`py-4 rounded-2xl text-[0.55rem] font-black flex flex-col items-center gap-2 border-2 transition-all ${delivery.method === m.id ? 'bg-primary-500 border-primary-500 text-white shadow-lg' : 'bg-white dark:bg-white/5 border-black/5 text-gray-400'}`}
               >
                 <m.icon size={18}/>
                 {m.id}
               </button>
             ))}
          </div>
       </div>

       <button 
         onClick={onComplete}
         className="w-full py-6 bg-gray-900 dark:bg-white text-white dark:text-black rounded-3xl font-black uppercase text-base tracking-[0.25em] shadow-2xl flex items-center justify-center gap-4 transition-all hover:scale-[1.02] active:scale-95"
       >
         <Coins size={24} className="text-primary-500"/>
         PROSES PEMBAYARAN
       </button>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white rounded-[3rem] overflow-hidden border border-black/5 shadow-2xl">
       {/* Header Navigation */}
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-primary-500/20"><Car size={24}/></div>
               <div>
                  <p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1">Matrix Store</p>
                  <h3 className="text-lg font-black uppercase tracking-tighter">Beli Asuransi Baru</h3>
               </div>
            </div>
            <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl">
               <div className="px-3 py-1 text-[0.6rem] font-black text-primary-500 uppercase tracking-widest">Step {step + 1}</div>
            </div>
          </div>
          <div className="flex gap-2">
             {STEPS.map((s, i) => (
               <div key={s.id} className={`h-1.5 rounded-full flex-1 transition-all duration-500 ${i === step ? 'bg-primary-500' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>
             ))}
          </div>
       </div>

       {/* Step Content */}
       <div className="flex-1 overflow-y-auto p-8 no-scrollbar">
          {step === 0 && renderStepVehicle()}
          {step === 1 && renderStepCoverage()}
          {step === 2 && renderStepProviders()}
          {step === 3 && renderStepKYC()}
          {step === 4 && renderStepSurvey()}
          {step === 5 && renderStepFinal()}
       </div>

       {/* Sticky Footer */}
       <div className="px-8 py-6 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-6 flex-shrink-0">
          <div className="flex-1">
             <p className="text-[0.55rem] font-black uppercase text-gray-400 leading-none mb-1 tracking-widest">Estimasi Premi</p>
             <p className="text-2xl font-black tracking-tighter text-primary-500">{formatIDR(calculatedPremium)}</p>
          </div>
          <div className="flex gap-3">
             {step > 0 && (
               <button onClick={handleBack} className="p-4 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-500 hover:text-primary-500 transition-colors">
                 <ChevronRight className="rotate-180" size={24}/>
               </button>
             )}
             <button 
               onClick={handleNext} 
               disabled={
                 step === STEPS.length - 1 || 
                 (step === 0 && (!vehicle.brand || !vehicle.model || vehicle.price === 0 || vehicle.plate.length < 5)) ||
                 (step === 2 && !selectedProvider) || 
                 (step === 3 && (kycData.ktp.length !== 16 || !kycData.name)) ||
                 (step === 4 && survey.score < 80 && !survey.manualVerif)
               }
               className="px-10 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.2em] shadow-2xl transition-all active:scale-95 disabled:opacity-30 flex items-center gap-2"
             >
               Lanjutkan <ChevronRight size={18}/>
             </button>
          </div>
       </div>
    </div>
  );
};

export default CarInsuranceWizard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Car, Shield, Zap, ChevronRight, MapPin, Camera, 
  CheckCircle2, AlertCircle, Loader2, FileSearch, 
  Trash2, ShieldCheck, Info, 
  Wallet, Star, Smartphone, CloudRain, Mail, Phone, 
  Printer, Coins, Percent, Building, Image as ImageIcon,
  Calendar, Check, Search, CreditCard, ScanFace, User,
  Briefcase, Building2, UserCheck, Timer, Plus, Edit3, Database
} from 'lucide-react';
import { CAR_DATABASE, getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS, TPL_OPTIONS } from '../constants';
import { extractKtpData, extractStnkData, analyzeVehicleSurvey } from '../services/geminiService';
import { InsuranceType } from '../types';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const STEPS = [
  { id: 'VEHICLE', label: 'Unit' },
  { id: 'COVERAGE', label: 'Polis' },
  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'SURVEY', label: 'Verif' },
  { id: 'FINAL', label: 'Bayar' }
];

const CarInsuranceWizard = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [entryMode, setEntryMode] = useState<'DATABASE' | 'MANUAL'>('DATABASE');

  // State Management
  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProvider, setSelectedProvider] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ name: '', ktp: '', address: '', email: '', phone: '', photo: null as string|null });
  const [survey, setSurvey] = useState({ stnk: null as string|null, photos: [] as string[], score: 0, manualVerif: false });
  const [delivery, setDelivery] = useState({ method: 'EMAIL', address: '', recipient: '' });

  // Update Year when condition changes
  useEffect(() => {
    if (vehicle.condition === 'NEW') {
        setVehicle(prev => ({ ...prev, year: 2025 }));
    }
  }, [vehicle.condition]);

  // Calculations
  const calculatedPremium = useMemo(() => {
    if (!vehicle.price) return 0;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    let totalRate = baseRate;

    if (coverage.authorized) totalRate += AUTHORIZED_WORKSHOP_RATE;
    if (coverage.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (coverage.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) totalRate += srccRate;

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) totalRate += tsRate;

    let prem = (vehicle.price * totalRate) / 100;

    // TPL Premium Logic: Every 10jt = 100rb premium
    if (coverage.tpl > 0) {
        const tplPremium = (coverage.tpl / 100); // (coverage.tpl / 10,000,000) * 100,000 simplifies to / 100
        prem += tplPremium;
    }

    let discVal = coverage.discount;
    if (coverage.discountType === 'PERCENT') {
        discVal = Math.min(coverage.discount, 25);
        prem = prem * (1 - discVal/100);
    } else {
        prem = Math.max(prem - discVal, prem * 0.75); 
    }

    return Math.round(prem);
  }, [vehicle, coverage]);

  const providerDetails = [
    { id: 'intra', name: 'Intra Asia', fee: 30000, coins: 0.15, pros: ['Termurah', 'Cepat'], cons: ['Banyak Pengecualian'] },
    { id: 'zurich', name: 'Zurich', fee: 55000, coins: 0.10, pros: ['Global Standard', 'Premium'], cons: ['Admin Mahal'] },
    { id: 'tugu', name: 'Tugu Insurance', fee: 50000, coins: 0.10, pros: ['BUMN Group', 'Aman'], cons: ['Proses Kaku'] }
  ];

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  // UX Helpers
  const formatInputCurrency = (value: string) => {
    const numeric = value.replace(/\D/g, "");
    if (!numeric) return "";
    return new Intl.NumberFormat('id-ID').format(parseInt(numeric));
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase();
    val = val.replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({
        ...vehicle, 
        plate, 
        region: regionInfo?.region || '3', 
        regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)'
      });
    } else {
      setVehicle({...vehicle, plate: val});
    }
  };

  const handleKtpUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setKycData(prev => ({ ...prev, photo: base64 }));
      const response = await extractKtpData(base64);
      setLoading(false);
      if (response.success && response.data) {
        setKycData(prev => ({
          ...prev,
          name: response.data.name || response.data.Name || prev.name,
          ktp: response.data.ktpNumber || response.data.ktp || response.data["KTP Number"] || prev.ktp,
          address: response.data.address || response.data.Address || prev.address
        }));
      }
    };
    reader.readAsDataURL(file);
  };

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey(prev => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      if (response.success && response.data) {
        const extractedPlate = response.data.plate || response.data.Plate || response.data.PlateNo;
        if (extractedPlate) {
          setVehicle(prev => ({ ...prev, plate: extractedPlate }));
        }
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    if (survey.photos.length < 5) return;
    setLoading(true);
    const response = await analyzeVehicleSurvey(survey.photos);
    setLoading(false);
    if (response.success) {
      const score = response.score || 0;
      setSurvey(prev => ({ 
        ...prev, 
        score,
        manualVerif: score < 80 
      }));
    } else {
      alert("Gagal melakukan audit neural.");
    }
  };

  const renderStepVehicle = () => (
    <div className="space-y-6 animate-fade-in">
      {/* Entry Mode Switcher */}
      <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-2xl">
         <button 
           onClick={() => setEntryMode('DATABASE')}
           className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-700 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Database size={14}/> Neural Database
         </button>
         <button 
           onClick={() => { setEntryMode('MANUAL'); setVehicle(v => ({ ...v, brand: '', model: '', basePrice: 0 })); }}
           className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-700 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Edit3 size={14}/> Manual Registry
         </button>
      </div>

      <div className="space-y-4">
        {/* Brand & Model Input Group */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Merk Kendaraan</label>
            {entryMode === 'DATABASE' ? (
                <div className="relative group">
                    <select 
                        className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-primary-500"
                        value={vehicle.brand}
                        onChange={(e) => {
                            const val = e.target.value;
                            const unit = CAR_DATABASE.find(c => c.brand === val);
                            const p = (unit?.yearPrices[2024] || 0) * 1000000;
                            setVehicle({...vehicle, brand: val, model: unit?.modelName || '', price: p, basePrice: p});
                        }}
                    >
                        <option value="">Pilih Merk</option>
                        {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400 group-hover:text-primary-500 transition-colors">
                        <ChevronRight className="rotate-90" size={18}/>
                    </div>
                </div>
            ) : (
                <input 
                    placeholder="Contoh: Toyota"
                    value={vehicle.brand}
                    className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm transition-all text-primary-500"
                    onChange={(e) => setVehicle({...vehicle, brand: e.target.value.toUpperCase()})}
                />
            )}
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Tipe Model</label>
            <input 
              readOnly={entryMode === 'DATABASE' && !vehicle.brand}
              placeholder={entryMode === 'DATABASE' ? (vehicle.brand ? `Model ${vehicle.brand}` : "Pilih Merk") : "Contoh: Avanza G"}
              value={vehicle.model}
              className={`w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm transition-all ${entryMode === 'DATABASE' ? 'bg-gray-50 dark:bg-black/20 text-gray-400' : 'text-primary-500'}`}
              onChange={(e) => setVehicle({...vehicle, model: e.target.value.toUpperCase()})}
            />
          </div>
        </div>

        {/* Year, Price, Plate UI */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Tahun</label>
            <select 
               className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm"
               value={vehicle.year}
               onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}
            >
               {vehicle.condition === 'NEW' ? (
                 <>
                    <option value={2025}>2025 (Gress)</option>
                    <option value={2024}>2024</option>
                 </>
               ) : (
                 Array.from({ length: 15 }, (_, i) => 2025 - i).map(y => <option key={y} value={y}>{y}</option>)
               )}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-[0.1em]">Harga OTR</label>
            <div className="relative group">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 font-black text-gray-400 text-sm">Rp</span>
              <input 
                type="text"
                inputMode="numeric"
                className="w-full pl-11 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 focus:border-primary-500 outline-none font-black text-lg transition-all text-primary-500"
                value={formatInputCurrency(vehicle.price.toString())}
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, "");
                  setVehicle({...vehicle, price: parseInt(val || "0"), manualPrice: true});
                }}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Plat Polisi</label>
            <div className="relative h-[68px] rounded-2xl bg-[#111] border-2 border-[#333] p-1 flex items-center justify-center overflow-hidden shadow-inner group">
               <input 
                 placeholder="B 1234 XYZ"
                 maxLength={12}
                 className="w-full bg-transparent text-center font-black text-2xl tracking-[0.25em] text-white uppercase outline-none placeholder:text-gray-800"
                 value={vehicle.plate}
                 onChange={handlePlateChange}
               />
               <div className="absolute right-4 text-[0.4rem] font-bold text-primary-500/50 uppercase tracking-widest">{vehicle.regionName}</div>
            </div>
          </div>
        </div>
      </div>

      {/* Usage Selection */}
      <div className="space-y-4">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.15em]">Tujuan & Kondisi Unit</label>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="grid grid-cols-3 gap-2">
                {[
                    { id: 'PRIVATE', icon: User, label: 'Pribadi' },
                    { id: 'COMMERCIAL', icon: Briefcase, label: 'Komersial' },
                    { id: 'DINAS', icon: Building2, label: 'Dinas' }
                ].map(u => (
                    <button 
                        key={u.id}
                        onClick={() => setVehicle({...vehicle, usage: u.id as any})}
                        className={`p-3 rounded-[1.5rem] border-2 flex flex-col items-center text-center gap-1.5 transition-all ${vehicle.usage === u.id ? 'border-primary-500 bg-primary-500/5 shadow-lg' : 'border-black/5 bg-white dark:bg-white/5'}`}
                    >
                        <u.icon size={20} className={vehicle.usage === u.id ? 'text-primary-500' : 'text-gray-400'}/>
                        <span className={`text-[0.55rem] font-black uppercase ${vehicle.usage === u.id ? 'text-primary-600' : 'text-gray-500'}`}>{u.label}</span>
                    </button>
                ))}
            </div>

            <div className="grid grid-cols-2 gap-2">
                {[
                    { id: 'NEW', icon: Zap, label: 'Gress (Baru)' },
                    { id: 'USED', icon: Timer, label: 'Second (Bekas)' }
                ].map(c => (
                    <button 
                        key={c.id}
                        onClick={() => setVehicle({...vehicle, condition: c.id as any})}
                        className={`p-3 rounded-[1.5rem] border-2 flex flex-col items-center text-center gap-1.5 transition-all ${vehicle.condition === c.id ? 'border-primary-500 bg-primary-500/5 shadow-lg' : 'border-black/5 bg-white dark:bg-white/5'}`}
                    >
                        <c.icon size={20} className={vehicle.condition === c.id ? 'text-primary-500' : 'text-gray-400'}/>
                        <span className={`text-[0.55rem] font-black uppercase ${vehicle.condition === c.id ? 'text-primary-600' : 'text-gray-500'}`}>{c.label}</span>
                    </button>
                ))}
            </div>
        </div>
      </div>
    </div>
  );

  const renderStepCoverage = () => (
    <div className="space-y-4 animate-fade-in">
       <div className="p-1 bg-gray-100 dark:bg-white/5 rounded-2xl flex gap-1">
          {([InsuranceType.COMPREHENSIVE, InsuranceType.TLO]).map(t => (
            <button 
              key={t}
              onClick={() => setCoverage({...coverage, type: t})}
              className={`flex-1 py-4 rounded-xl text-[0.7rem] font-black uppercase transition-all flex flex-col items-center gap-1 ${coverage.type === t ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-xl' : 'text-gray-400'}`}
            >
              {t}
              <span className="text-[0.45rem] font-bold opacity-60 tracking-normal capitalize">{t === 'COMPREHENSIVE' ? 'All Risk' : 'Total Loss Only'}</span>
            </button>
          ))}
       </div>

       {/* TPL Options Menu */}
       <div className="space-y-2">
          <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Limit TPL (Pihak Ketiga)</label>
          <div className="grid grid-cols-4 gap-2">
             {TPL_OPTIONS.slice(0, 4).map(val => (
                <button 
                   key={val}
                   onClick={() => setCoverage({...coverage, tpl: val * 1000000})}
                   className={`p-3 rounded-xl border-2 font-black text-[0.6rem] transition-all ${coverage.tpl === val * 1000000 ? 'border-primary-500 bg-primary-500/5 text-primary-500' : 'border-black/5 bg-white dark:bg-white/5 text-gray-400'}`}
                >
                   {val === 0 ? 'NONE' : `${val}JT`}
                </button>
             ))}
          </div>
          <p className="text-[0.5rem] font-bold text-gray-400 ml-1 italic">* Premi TPL: Rp 100rb per kelipatan 10jt limit.</p>
       </div>

