    if (step === 3) return kycData.name && kycData.ktp.length === 16;
    if (step === 5) return survey.score >= 80 || survey.manualVerif;
    return true;
  }, [step, vehicle, selectedProvider, kycData, survey]);

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white rounded-[3rem] overflow-hidden border border-black/5 shadow-2xl">
