            {loading && <div className="absolute inset-0 bg-white/80 dark:bg-black/80 flex flex-col items-center justify-center gap-2 z-10"><Loader2 className="animate-spin text-primary-500" /><p className="text-[0.5rem] font-black uppercase tracking-widest text-primary-500">Neural OCR Analysis...</p></div>}
          </div>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 gap-4 px-1">
          <div className="space-y-1.5">
             <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">Nama Sesuai KTP</label>
             <input placeholder="Nama Lengkap" value={kycData.name} className="w-full p-4 bg-white dark:bg-white/5 border-2 border-black/5 rounded-2xl text-xs font-bold focus:border-primary-500 outline-none transition-all" onChange={(e) => setKycData({...kycData, name: e.target.value})}/>
          </div>
