import React, { useState, useMemo, useEffect } from 'react';
import { 
  Car, Shield, Zap, ChevronRight, MapPin, Camera, 
  CheckCircle2, AlertCircle, Loader2, FileSearch, 
  Trash2, ShieldCheck, Info, 
  Wallet, Star, Smartphone, CloudRain, Mail, Phone, 
  Printer, Coins, Percent, Building, Image as ImageIcon,
  Calendar, Check, Search, CreditCard, ScanFace, User,
  Briefcase, Building2, UserCheck, Timer, Plus, Edit3, Database,
  ArrowDown, ChevronDown, ClipboardList
} from 'lucide-react';
import { CAR_DATABASE, getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS, TPL_OPTIONS, INSURANCE_PROVIDERS } from '../constants';
import { extractKtpData, extractStnkData, analyzeVehicleSurvey } from '../services/geminiService';
import { InsuranceType } from '../types';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const STEPS = [
  { id: 'VEHICLE', label: 'Unit' },
  { id: 'COVERAGE', label: 'Polis' },
  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'PRESUMMARY', label: 'Rincian' },
  { id: 'SURVEY', label: 'Audit' },
  { id: 'FINAL', label: 'Bayar' }
];

const CarInsuranceWizard = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [entryMode, setEntryMode] = useState<'DATABASE' | 'MANUAL'>('DATABASE');
  const [showBreakdown, setShowBreakdown] = useState(false);

  // State Management
  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ name: '', ktp: '', address: '', email: '', phone: '', photo: null as string|null });

  const [stnkVerification, setStnkVerification] = useState<{plate?: string, vin?: string, engine?: string, brand?: string} | null>(null);
  const [survey, setSurvey] = useState({ stnk: null as string|null, photos: [] as string[], score: 0, manualVerif: false, accessories: '' });
  const [delivery, setDelivery] = useState({ method: 'EMAIL', address: '', recipient: '' });

  // Update Year when condition changes
  useEffect(() => {
    if (vehicle.condition === 'NEW') {
        setVehicle(prev => ({ ...prev, year: 2025 }));
    }
  }, [vehicle.condition]);

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  // Comprehensive Calculations Breakdown
  const premiumBreakdown = useMemo(() => {
    if (!vehicle.price) return null;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);

    const basicPremium = (vehicle.price * baseRate) / 100;

    const expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Resmi (Authorized)', val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100, rate: AUTHORIZED_WORKSHOP_RATE });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100, rate: EXPANSION_RATES.FLOOD });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100, rate: EXPANSION_RATES.EARTHQUAKE });

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', val: (vehicle.price * srccRate) / 100, rate: srccRate });

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', val: (vehicle.price * tsRate) / 100, rate: tsRate });

    // TPL Premium Fix: 100k per 10m limit
    const tplPremium = (coverage.tpl / 100); 

    const expansionTotal = expansions.reduce((acc, curr) => acc + curr.val, 0) + tplPremium;
    const adminFee = selectedProvider?.adminFee || 50000;
    const netPremium = basicPremium + expansionTotal;
    const totalPayable = netPremium + adminFee + STAMP_DUTY;

    return {
        baseRate,
        basicPremium,
        expansions,
        tplPremium,
        adminFee,
        stampDuty: STAMP_DUTY,
        netPremium,
        totalPayable
    };
  }, [vehicle, coverage, selectedProvider]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const formatInputCurrency = (value: string) => {
    const numeric = value.replace(/\D/g, "");
    if (!numeric) return "";
    return new Intl.NumberFormat('id-ID').format(parseInt(numeric));
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase();
    val = val.replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({
        ...vehicle, 
        plate, 
        region: regionInfo?.region || '3', 
        regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)'
      });
    } else {
      setVehicle({...vehicle, plate: val});
    }
  };

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey(prev => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      if (response.success && response.data) {
        setStnkVerification({
            plate: response.data.Plate || response.data.PlateNo || response.data.plate,
            vin: response.data.ChassisNo || response.data.VIN || response.data.vin,
            engine: response.data.EngineNo || response.data.engine,
            brand: response.data.Brand || response.data.brand
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    if (survey.photos.length < 5) return;
    setLoading(true);
    const response = await analyzeVehicleSurvey(survey.photos);
    setLoading(false);
    if (response.success) {
      const score = response.score || 0;
      setSurvey(prev => ({ ...prev, score, manualVerif: score < 80 }));
    }
  };

  const renderStepVehicle = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-2xl">
         <button 
           onClick={() => setEntryMode('DATABASE')}
           className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-700 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Database size={14}/> Neural Database
         </button>
         <button 
           onClick={() => { setEntryMode('MANUAL'); setVehicle(v => ({ ...v, brand: '', model: '', basePrice: 0 })); }}
           className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-700 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Edit3 size={14}/> Manual Registry
         </button>
      </div>

      <div className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Merk Kendaraan</label>
            {entryMode === 'DATABASE' ? (
                <div className="relative group">
                    <select 
                        className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-primary-500"
                        value={vehicle.brand}
                        onChange={(e) => {
                            const val = e.target.value;
                            const unit = CAR_DATABASE.find(c => c.brand === val);
                            const p = (unit?.yearPrices[2024] || 0) * 1000000;
                            setVehicle({...vehicle, brand: val, model: unit?.modelName || '', price: p, basePrice: p});
                        }}
                    >
                        <option value="">Pilih Merk</option>
                        {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                    <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                        <ChevronRight className="rotate-90" size={18}/>
                    </div>
                </div>
            ) : (
                <input 
                    placeholder="Contoh: Toyota"
                    value={vehicle.brand}
                    className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm transition-all text-primary-500"
                    onChange={(e) => setVehicle({...vehicle, brand: e.target.value.toUpperCase()})}
                />
            )}
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Tipe Model</label>
            <input 
              readOnly={entryMode === 'DATABASE' && !vehicle.brand}
              placeholder={entryMode === 'DATABASE' ? (vehicle.brand ? `Model ${vehicle.brand}` : "Pilih Merk") : "Contoh: Avanza G"}
              value={vehicle.model}
              className={`w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm transition-all ${entryMode === 'DATABASE' ? 'bg-gray-50 dark:bg-black/20 text-gray-400' : 'text-primary-500'}`}
              onChange={(e) => setVehicle({...vehicle, model: e.target.value.toUpperCase()})}
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Tahun</label>
            <select 
               className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm"
               value={vehicle.year}
               onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}
            >
               {vehicle.condition === 'NEW' ? (
                 <>
                    <option value={2025}>2025 (Gress)</option>
                    <option value={2024}>2024</option>
                 </>
               ) : (
                 Array.from({ length: 15 }, (_, i) => 2025 - i).map(y => <option key={y} value={y}>{y}</option>)
               )}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 tracking-[0.1em]">Harga OTR</label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 font-black text-gray-400 text-sm">Rp</span>
              <input 
                type="text"
                inputMode="numeric"
                className="w-full pl-11 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 focus:border-primary-500 outline-none font-black text-lg text-primary-500"
                value={formatInputCurrency(vehicle.price.toString())}
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, "");
                  setVehicle({...vehicle, price: parseInt(val || "0"), manualPrice: true});
                }}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.1em]">Plat Polisi</label>
            <div className="relative h-[68px] rounded-2xl bg-[#111] border-2 border-[#333] p-1 flex items-center justify-center shadow-inner group">
               <input 
                 placeholder="B 1234 XYZ"
                 maxLength={12}
                 className="w-full bg-transparent text-center font-black text-2xl tracking-[0.25em] text-white uppercase outline-none placeholder:text-gray-800"
                 value={vehicle.plate}
                 onChange={handlePlateChange}
               />
               <div className="absolute right-4 text-[0.4rem] font-bold text-primary-500/50 uppercase tracking-widest">{vehicle.regionName}</div>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-4">
        <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-1 tracking-[0.15em]">Tujuan & Kondisi Unit</label>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="grid grid-cols-3 gap-2">
                {[
                    { id: 'PRIVATE', icon: User, label: 'Pribadi' },
                    { id: 'COMMERCIAL', icon: Briefcase, label: 'Komersial' },
                    { id: 'DINAS', icon: Building2, label: 'Dinas' }
                ].map(u => (
                    <button 
