                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><Smartphone size={12}/> Nomor Plat</span>
                <span className="font-black text-right tracking-[0.1em]">{vehicle.plate}</span>
             </div>
             <div className="flex justify-between items-center text-[0.65rem]">
                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><Shield size={12}/> Jenis Polis</span>
                <span className="font-black text-right text-primary-500">{coverage.type}</span>
             </div>
             <div className="flex justify-between items-center text-[0.65rem]">
                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><User size={12}/> Penanggung</span>
                <span className="font-black text-right">{selectedProvider?.name}</span>
             </div>
          </div>
       </div>

       <div className="space-y-3">
          <label className="text-[0.65rem] font-black uppercase text-gray-500 ml-2 tracking-widest">Metode Pengiriman Polis</label>
          <div className="grid grid-cols-3 gap-2">
             {[
               { id: 'WHATSAPP', icon: Smartphone },
               { id: 'EMAIL', icon: Mail },
               { id: 'HARDCOPY', icon: Building }
             ].map(m => (
               <button 
                 key={m.id} 
                 onClick={() => setDelivery({...delivery, method: m.id as any})}
                 className={`py-4 rounded-2xl text-[0.55rem] font-black flex flex-col items-center gap-2 border-2 transition-all ${delivery.method === m.id ? 'bg-primary-500 border-primary-500 text-white shadow-lg' : 'bg-white dark:bg-white/5 border-black/5 text-gray-400'}`}
               >
                 <m.icon size={18}/>
                 {m.id}
               </button>
             ))}
          </div>
       </div>

       <button 
         onClick={onComplete}
         className="w-full py-6 bg-gray-900 dark:bg-white text-white dark:text-black rounded-3xl font-black uppercase text-base tracking-[0.25em] shadow-2xl flex items-center justify-center gap-4 transition-all hover:scale-[1.02] active:scale-95"
       >
         <Coins size={24} className="text-primary-500"/>
         PROSES PEMBAYARAN
       </button>
    </div>
  );

  const canContinue = useMemo(() => {
    if (step === 0) return vehicle.brand && vehicle.model && vehicle.price > 0 && vehicle.plate.length >= 5;
    if (step === 2) return selectedProviderId !== null;
    if (step === 3) return kycData.name && kycData.ktp.length === 16;
    if (step === 5) return survey.score >= 80 || survey.manualVerif;
    return true;
  }, [step, vehicle, selectedProviderId, kycData, survey]);

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white rounded-[3rem] overflow-hidden border border-black/5 shadow-2xl relative">
       {/* Header Navigation */}
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-primary-500/20"><Car size={24}/></div>
               <div>
                  <p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1">Matrix Store</p>
                  <h3 className="text-lg font-black uppercase tracking-tighter">Beli Asuransi Baru</h3>
               </div>
            </div>
            <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl">
               <div className="px-3 py-1 text-[0.6rem] font-black text-primary-500 uppercase tracking-widest">Step {step + 1}</div>
            </div>
          </div>
          <div className="flex gap-2">
             {STEPS.map((s, i) => (
               <div key={s.id} className={`h-1.5 rounded-full flex-1 transition-all duration-500 ${i === step ? 'bg-primary-500' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>
             ))}
          </div>
       </div>

       {/* Step Content */}
       <div className="flex-1 overflow-y-auto p-8 no-scrollbar">
          {step === 0 && renderStepVehicle()}
          {step === 1 && renderStepCoverage()}
          {step === 2 && renderStepProviders()}
          {step === 3 && renderStepKYC()}
          {step === 4 && renderStepPreSummary()}
          {step === 5 && renderStepSurvey()}
          {step === 6 && renderStepFinal()}
       </div>

       {/* Sticky Footer */}
       <div className="px-8 py-6 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-6 flex-shrink-0">
          <div className="flex-1">
             <p className="text-[0.55rem] font-black uppercase text-gray-400 leading-none mb-1 tracking-widest">Estimasi Premi</p>
             <p className="text-2xl font-black tracking-tighter text-primary-500">{formatIDR(premiumBreakdown?.totalPayable || 0)}</p>
          </div>
          <div className="flex gap-3">
             {step > 0 && (
               <button onClick={handleBack} className="p-4 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-500 hover:text-primary-500 transition-colors">
                 <ChevronRight className="rotate-180" size={24}/>
               </button>
             )}
             <button 
               onClick={handleNext} 
               disabled={step === STEPS.length - 1 || !canContinue}
               className="px-10 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.2em] shadow-2xl transition-all active:scale-95 disabled:opacity-30 flex items-center gap-2"
             >
               Lanjutkan <ChevronRight size={18}/>
             </button>
          </div>
       </div>
    </div>
  );
};

export default CarInsuranceWizard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Car, Shield, Zap, ChevronRight, MapPin, Camera, 
  CheckCircle2, AlertCircle, Loader2, FileSearch, 
  Trash2, ShieldCheck, Info, 
  Wallet, Star, Smartphone, CloudRain, Mail, Phone, 
  Printer, Coins, Percent, Building, Image as ImageIcon,
  Calendar, Check, Search, CreditCard, ScanFace, User,
  Briefcase, Building2, UserCheck, Timer, Plus, Edit3, Database,
  ArrowDown, ChevronDown, ClipboardList, Palette
} from 'lucide-react';
import { CAR_DATABASE, getOJKRate, EXPANSION_RATES, AUTHORIZED_WORKSHOP_RATE, STAMP_DUTY, PLATE_REGIONS, TPL_OPTIONS, INSURANCE_PROVIDERS } from '../constants';
import { extractKtpData, extractStnkData, analyzeVehicleSurvey } from '../services/geminiService';
import { InsuranceType } from '../types';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const STEPS = [
  { id: 'VEHICLE', label: 'Unit' },
  { id: 'COVERAGE', label: 'Polis' },
  { id: 'PROVIDERS', label: 'Opsi' },
  { id: 'KYC', label: 'Nasabah' },
  { id: 'PRESUMMARY', label: 'Rincian' },
  { id: 'SURVEY', label: 'Audit' },
  { id: 'FINAL', label: 'Bayar' }
];

const CarInsuranceWizard = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [entryMode, setEntryMode] = useState<'DATABASE' | 'MANUAL'>('DATABASE');
  const [isEditingStnk, setIsEditingStnk] = useState(false);

  // State Management
  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ name: '', ktp: '', address: '', email: '', phone: '', photo: null as string|null });

  const [stnkVerification, setStnkVerification] = useState<{plate?: string, vin?: string, engine?: string, brand?: string, color?: string} | null>(null);
  const [survey, setSurvey] = useState({ stnk: null as string|null, photos: [null, null, null, null, null] as (string|null)[], score: 0, manualVerif: false, accessories: '' });
  const [delivery, setDelivery] = useState({ method: 'EMAIL', address: '', recipient: '' });

  // Update Year when condition changes
  useEffect(() => {
    if (vehicle.condition === 'NEW') {
        setVehicle(prev => ({ ...prev, year: 2025 }));
    }
  }, [vehicle.condition]);

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  const calculatedPremium = useMemo(() => {
    if (!vehicle.price) return 0;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    let totalRate = baseRate;

    if (coverage.authorized) totalRate += AUTHORIZED_WORKSHOP_RATE;
    if (coverage.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (coverage.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) totalRate += srccRate;

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) totalRate += tsRate;

    let prem = (vehicle.price * totalRate) / 100;
    if (coverage.tpl > 0) prem += (coverage.tpl / 100);

    return Math.round(prem);
  }, [vehicle, coverage]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey(prev => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      if (response.success && response.data) {
        setStnkVerification({
            plate: response.data.Plate || response.data.PlateNo || response.data.plate,
            vin: response.data.ChassisNo || response.data.VIN || response.data.vin,
            engine: response.data.EngineNo || response.data.engine,
            brand: response.data.Brand || response.data.brand,
            color: response.data.Color || response.data.Warna || response.data.color
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const validPhotos = survey.photos.filter(p => !!p) as string[];
    if (validPhotos.length < 5) return;
    setLoading(true);
    const response = await analyzeVehicleSurvey(validPhotos);
    setLoading(false);
    if (response.success) {
      const score = response.score || 0;
      setSurvey(prev => ({ ...prev, score, manualVerif: score < 80 }));
    }
  };

  const renderStepVehicle = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-2xl">
         <button onClick={() => setEntryMode('DATABASE')} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-700 shadow-xl text-primary-500' : 'text-gray-400'}`}>Database</button>
         <button onClick={() => setEntryMode('MANUAL')} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-700 shadow-xl text-primary-500' : 'text-gray-400'}`}>Manual</button>
      </div>
      <div className="space-y-4">
        <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">Merk</label>
                {entryMode === 'DATABASE' ? (
                    <select className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm outline-none" value={vehicle.brand} onChange={(e) => setVehicle({...vehicle, brand: e.target.value})}>
                        <option value="">Pilih</option>
                        {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                ) : <input className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm outline-none" value={vehicle.brand} onChange={(e) => setVehicle({...vehicle, brand: e.target.value.toUpperCase()})}/>}
            </div>
            <div className="space-y-1">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">Model</label>
                <input className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm outline-none" value={vehicle.model} onChange={(e) => setVehicle({...vehicle, model: e.target.value.toUpperCase()})}/>
            </div>
        </div>
        <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">Tahun</label>
                <select className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm outline-none" value={vehicle.year} onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}>
                    {Array.from({length: 15}, (_, i) => 2025 - i).map(y => <option key={y} value={y}>{y}</option>)}
                </select>
            </div>
            <div className="space-y-1">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-1">Harga (IDR)</label>
                <input className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm outline-none" type="number" value={vehicle.price} onChange={(e) => setVehicle({...vehicle, price: parseInt(e.target.value)})}/>
            </div>
        </div>
      </div>
    </div>
  );

  const renderStepCoverage = () => (
    <div className="space-y-5 animate-fade-in">
       <div className="p-1 bg-gray-100 dark:bg-white/5 rounded-2xl flex gap-1">
          {([InsuranceType.COMPREHENSIVE, InsuranceType.TLO]).map(t => (
            <button key={t} onClick={() => setCoverage({...coverage, type: t})} className={`flex-1 py-4 rounded-xl text-[0.7rem] font-black uppercase transition-all ${coverage.type === t ? 'bg-white dark:bg-gray-700 text-primary-500 shadow-xl' : 'text-gray-400'}`}>{t}</button>
          ))}
       </div>
       <div className="grid grid-cols-2 gap-2.5">
          {[{ id: 'authorized', label: 'Authorized', icon: Building }, { id: 'flood', label: 'Banjir', icon: CloudRain }, { id: 'earthquake', label: 'Gempa', icon: Zap }, { id: 'srcc', label: 'SRCC', icon: AlertCircle }].map(opt => (
            <button key={opt.id} onClick={() => setCoverage({...coverage, [opt.id]: !coverage[opt.id as keyof typeof coverage]})} className={`p-4 rounded-2xl border-2 text-left flex flex-col gap-1.5 transition-all ${coverage[opt.id as keyof typeof coverage] ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5 opacity-80'}`}>
              <opt.icon size={20} className={coverage[opt.id as keyof typeof coverage] ? 'text-primary-500' : 'text-gray-300'}/>
              <p className="text-[0.6rem] font-black uppercase">{opt.label}</p>
            </button>
          ))}
       </div>
    </div>
  );

  const renderStepProviders = () => (
    <div className="space-y-3 animate-fade-in">
       {INSURANCE_PROVIDERS.map(p => (
         <div key={p.id} onClick={() => setSelectedProviderId(p.id)} className={`p-5 rounded-[2rem] border-2 cursor-pointer transition-all relative overflow-hidden group ${selectedProviderId === p.id ? 'border-primary-500 bg-primary-500/5 shadow-xl' : 'border-black/5 bg-white dark:bg-white/5 grayscale opacity-60'}`}>
           <div className="flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg ${selectedProviderId === p.id ? 'bg-primary-500 text-white' : 'bg-gray-100'}`}>{p.name[0]}</div>
                <h4 className="font-black text-sm uppercase">{p.name}</h4>
              </div>
              <div className="text-right">
                <p className="text-lg font-black text-primary-500 leading-none">{formatIDR(calculatedPremium + p.adminFee + STAMP_DUTY)}</p>
                <p className="text-[0.45rem] text-gray-400 uppercase font-bold mt-1 tracking-widest">Total Premi</p>
              </div>
           </div>
           {selectedProviderId === p.id && <div className="absolute top-0 right-0 p-4"><div className="w-6 h-6 bg-primary-500 rounded-full flex items-center justify-center text-white shadow-lg"><Check size={14} strokeWidth={4}/></div></div>}
         </div>
       ))}
    </div>
  );

  const renderStepKYC = () => (
    <div className="space-y-6 animate-fade-in">
       <div className="space-y-4">
          <input placeholder="NAMA LENGKAP" className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm outline-none" value={kycData.name} onChange={(e) => setKycData({...kycData, name: e.target.value.toUpperCase()})}/>
          <input placeholder="NOMOR KTP" className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 font-black text-sm outline-none" value={kycData.ktp} onChange={(e) => setKycData({...kycData, ktp: e.target.value.replace(/\D/g, "")})}/>
          <div className="p-4 bg-primary-500/5 rounded-[2rem] border-2 border-dashed border-primary-500/20 text-center relative cursor-pointer">
             {loading ? <Loader2 className="animate-spin mx-auto text-primary-500" size={24}/> : <p className="text-[0.55rem] font-black uppercase text-primary-500">Upload KTP</p>}
             <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => {/* Handle upload logic */}}/>
          </div>
       </div>
    </div>
  );

  // REVERT: Step 4 Simple Summary
  const renderStepPreSummary = () => (
    <div className="space-y-6 animate-fade-in">
       <div className="p-6 bg-white dark:bg-white/5 rounded-[2.5rem] border-2 border-black/5 space-y-6 shadow-xl relative overflow-hidden">
          <div className="absolute right-0 top-0 p-6 opacity-5"><ShieldCheck size={100}/></div>
          <div className="flex justify-between items-start relative z-10">
             <div>
               <p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-[0.3em]">Preliminary Quote</p>
               <h4 className="text-2xl font-black uppercase tracking-tighter text-primary-500">{vehicle.brand} {vehicle.model}</h4>
             </div>
             <div className="p-3 bg-primary-500/10 rounded-2xl text-primary-500"><Info size={18}/></div>
          </div>

          <div className="grid grid-cols-1 gap-4 pt-4 border-t border-black/5 relative z-10">
             <div className="flex justify-between items-center text-[0.65rem]">
                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><Car size={12}/> Unit Kendaraan</span>
                <span className="font-black text-right">{vehicle.brand} {vehicle.model} ({vehicle.year})</span>
             </div>
             <div className="flex justify-between items-center text-[0.65rem]">
                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><Smartphone size={12}/> Nomor Plat</span>
                <span className="font-black text-right tracking-[0.1em]">{vehicle.plate}</span>
             </div>
             <div className="flex justify-between items-center text-[0.65rem]">
                <span className="text-gray-400 font-bold uppercase tracking-widest flex items-center gap-2"><Shield size={12}/> Tipe Proteksi</span>
                <span className="font-black text-right text-primary-500">{coverage.type}</span>
             </div>
             <div className="mt-4 p-4 bg-primary-500/5 rounded-2xl border border-primary-500/10">
                <div className="flex justify-between items-center mb-1">
                    <span className="text-[0.45rem] font-black text-gray-400 uppercase tracking-widest">Total Premi Net</span>
                    <span className="text-xl font-black text-primary-500">{formatIDR(calculatedPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY)}</span>
                </div>
                <p className="text-[0.4rem] font-bold text-gray-400 uppercase italic">Sudah termasuk biaya admin & materai.</p>
             </div>
          </div>
       </div>
    </div>
  );

  const renderStepSurvey = () => (
    <div className="space-y-4 animate-fade-in h-full flex flex-col relative">
       {/* FIXED PHOTO GRID AT TOP */}
       <div className="flex-shrink-0 grid grid-cols-5 gap-2 p-1 bg-gray-100 dark:bg-white/5 rounded-2xl sticky top-0 z-20">
          {['Depan', 'Blkng', 'Kanan', 'Kiri', 'Int'].map((label, i) => (
            <div key={i} className="relative aspect-square bg-white dark:bg-white/10 rounded-xl overflow-hidden border border-black/5 group">
                {survey.photos[i] ? (
                    <img src={survey.photos[i]!} className="w-full h-full object-cover" alt={label}/>
                ) : (
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                        <Camera size={14} className="text-gray-300"/>
                        <span className="text-[0.35rem] font-black uppercase text-gray-400 mt-0.5">{label}</span>
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => {
                            const file = e.target.files?.[0];
                            if(!file) return;
                            const r = new FileReader();
                            r.onload = () => {
                                const np = [...survey.photos];
                                np[i] = r.result as string;
                                setSurvey({...survey, photos: np});
                            };
                            r.readAsDataURL(file);
                        }}/>
                    </div>
                )}
                {survey.photos[i] && <button onClick={() => { const np = [...survey.photos]; np[i]=null; setSurvey({...survey, photos: np}); }} className="absolute top-0 right-0 p-1 bg-black/50 text-white"><X size={8}/></button>}
            </div>
          ))}
       </div>

       {/* Audit Score Header */}
       <div className="p-4 bg-gray-900 text-white rounded-[2rem] flex items-center justify-between shadow-xl relative overflow-hidden flex-shrink-0">
          <div className="flex items-center gap-3 relative z-10">
            <div className="w-10 h-10 bg-primary-500/20 rounded-xl flex items-center justify-center text-primary-400"><ShieldCheck size={20}/></div>
            <div>
              <p className="text-[0.4rem] font-black uppercase text-gray-400 tracking-widest">Audit Score</p>
              <p className="text-xl font-black">{survey.score}%</p>
            </div>
          </div>
          <button onClick={runSurveyAI} disabled={loading || survey.photos.some(p => p === null)} className="px-4 py-2 bg-primary-500 text-white rounded-xl text-[0.55rem] font-black uppercase disabled:opacity-50">Audit Fisik</button>
       </div>

       {/* STNK Analysis & Editable Fields */}
       <div className="flex-1 overflow-y-auto no-scrollbar space-y-4 pb-4">
            <div className="p-5 bg-white dark:bg-white/5 border border-black/5 rounded-[2rem] space-y-4">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <FileSearch size={18} className="text-primary-500"/>
                        <span className="text-xs font-black uppercase tracking-widest">STNK Neural Scan</span>
                    </div>
                    {!stnkVerification && (
                        <button onClick={() => document.getElementById('stnk-upload-2')?.click()} className="flex items-center gap-2 px-4 py-2 bg-primary-500/10 text-primary-500 rounded-xl text-[0.55rem] font-black uppercase">
                            {loading ? <Loader2 size={12} className="animate-spin"/> : <Camera size={12}/>} Scan Dokumen
                        </button>
                    )}
                    <input id="stnk-upload-2" type="file" className="hidden" onChange={handleStnkUpload}/>
                </div>

                {stnkVerification && (
                    <div className="space-y-4 animate-fade-in">
                        <div className="flex justify-between items-center px-1">
                            <span className="text-[0.5rem] font-black text-gray-400 uppercase tracking-widest">Data Terdeteksi</span>
                            <button onClick={() => setIsEditingStnk(!isEditingStnk)} className="flex items-center gap-1.5 text-primary-500 font-black text-[0.55rem] uppercase">
                                {isEditingStnk ? <CheckCircle2 size={12}/> : <Edit3 size={12}/>} {isEditingStnk ? 'Simpan' : 'Edit Data'}
                            </button>
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            {[
                                { label: 'No. Plat', value: stnkVerification.plate, key: 'plate', icon: Smartphone },
                                { label: 'No. Rangka', value: stnkVerification.vin, key: 'vin', icon: Shield },
                                { label: 'No. Mesin', value: stnkVerification.engine, key: 'engine', icon: Zap },
                                { label: 'Warna', value: stnkVerification.color, key: 'color', icon: Palette },
                                { label: 'Merek', value: stnkVerification.brand, key: 'brand', icon: Car }
                            ].map((item) => (
                                <div key={item.key} className="p-3 bg-gray-100 dark:bg-white/5 rounded-xl border border-black/5">
                                    <div className="flex items-center gap-1.5 mb-1 opacity-50">
                                        <item.icon size={10}/>
                                        <p className="text-[0.4rem] font-black uppercase tracking-tighter">{item.label}</p>
                                    </div>
                                    {isEditingStnk ? (
                                        <input 
                                            className="w-full bg-white dark:bg-black/20 font-black text-[0.6rem] text-primary-600 outline-none border-b border-primary-500/30 pb-0.5" 
                                            value={item.value || ''} 
                                            onChange={(e) => setStnkVerification({...stnkVerification, [item.key]: e.target.value.toUpperCase()})}
                                        />
                                    ) : (
                                        <p className="font-black text-[0.65rem] text-gray-900 dark:text-white uppercase truncate">{item.value || 'N/A'}</p>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            <div className="space-y-1 px-1">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Aksesoris Non-Standar</label>
                <textarea placeholder="Contoh: Velg, Audio, Bodykit..." className="w-full p-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 outline-none text-xs font-medium resize-none h-20" value={survey.accessories} onChange={(e) => setSurvey({...survey, accessories: e.target.value})}/>
            </div>
       </div>
    </div>
  );

  const renderStepFinal = () => (
    <div className="space-y-6 animate-fade-in text-center py-6">
       <div className="w-20 h-20 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl"><Check size={40} strokeWidth={4}/></div>
       <div className="space-y-2">
         <h3 className="text-2xl font-black uppercase tracking-tighter">Siap Dibayar</h3>
         <p className="text-xs text-gray-500 font-bold uppercase tracking-widest px-6">Seluruh data telah terverifikasi secara neural. Silahkan lanjutkan ke gerbang pembayaran.</p>
       </div>
       <button onClick={onComplete} className="w-full py-6 bg-gray-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-base tracking-widest shadow-2xl flex items-center justify-center gap-4 transition-all hover:scale-105">
          <Coins size={24} className="text-primary-500"/> BAYAR {formatIDR(calculatedPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY)}
       </button>
    </div>
  );

  const canContinue = useMemo(() => {
    if (step === 0) return vehicle.brand && vehicle.model && vehicle.price > 0 && vehicle.plate.length >= 5;
    if (step === 2) return selectedProviderId !== null;
    if (step === 3) return kycData.name && kycData.ktp.length >= 10;
    if (step === 5) return stnkVerification !== null;
    return true;
  }, [step, vehicle, selectedProviderId, kycData, stnkVerification]);

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white rounded-[3rem] overflow-hidden border border-black/5 shadow-2xl relative">
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-primary-500/20"><Car size={24}/></div>
               <div>
                  <p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-[0.4em] mb-1">Matrix Store</p>
                  <h3 className="text-lg font-black uppercase tracking-tighter">Asuransi Mobil</h3>
               </div>
            </div>
            <div className="px-3 py-1 bg-gray-100 dark:bg-white/5 rounded-xl text-[0.6rem] font-black text-primary-500 uppercase tracking-widest">S{step + 1}</div>
          </div>
          <div className="flex gap-1.5">
             {STEPS.map((s, i) => <div key={s.id} className={`h-1.5 rounded-full flex-1 transition-all ${i === step ? 'bg-primary-500 w-8' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>)}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-6 no-scrollbar">
          {step === 0 && renderStepVehicle()}
          {step === 1 && renderStepCoverage()}
          {step === 2 && renderStepProviders()}
          {step === 3 && renderStepKYC()}
          {step === 4 && renderStepPreSummary()}
          {step === 5 && renderStepSurvey()}
          {step === 6 && renderStepFinal()}
       </div>

       <div className="px-8 py-5 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-4 flex-shrink-0">
          <div className="flex-1">
             <p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-widest mb-1">Estimasi</p>
             <p className="text-xl font-black tracking-tighter text-primary-500">{formatIDR(calculatedPremium)}</p>
          </div>
          <div className="flex gap-2">
             {step > 0 && <button onClick={handleBack} className="p-4 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-400"><ChevronRight className="rotate-180" size={20}/></button>}
             <button onClick={handleNext} disabled={step === STEPS.length - 1 || !canContinue} className="px-8 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.65rem] tracking-widest shadow-xl disabled:opacity-30 flex items-center gap-2">Lanjut <ChevronRight size={14}/></button>
          </div>
       </div>
    </div>
  );
};

// Added missing X icon
const X = ({ size, className }: { size: number, className?: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M18 6 6 18M6 6l12 12"/></svg>
);

export default CarInsuranceWizard;
